/* uc16/fisiopato · gerado por medicina/bancos.py a partir de UC16_Fisiopato.json — não editar à mão */
window.UC={"banco":[{"id":"UC16-FIS-T3-Q01","sp":1,"tus":["T3"],"prova":"T3 (2022/2) Q1","selo":"OF","tipo":"sentenças","tema":"Hipóteses da depressão","enun":"Analise as seguintes afirmativas sobre a depressão e assinale abaixo a alternativa correta:","itens":["1. A hipótese monoaminérgica preconiza que na depressão há níveis reduzidos de serotonina e dopamina.","2. A hipótese neurotrófica associa a diminuição da expressão de BDNF e consequente atrofia de estruturas límbicas com a depressão.","3. No stress crônico, a ativação das vias inflamatórias como a ativada pelo NF-kB, pode se tornar mais sensível para o efeito inibitório do cortisol."],"alts":["Somente a afirmativa 1 é correta.","Somente a afirmativa 2 é correta.","Somente as afirmativas 1 e 2 são corretas.","Somente as afirmativas 2 e 3 são corretas.","Todas as afirmativas são corretas"],"gab":"C","com":"No estresse crônico as vias inflamatórias ficam MENOS sensíveis ao efeito inibitório do cortisol (resistência a glicocorticoide); por isso a 3 é falsa. 1 e 2 descrevem as hipóteses monoaminérgica e neurotrófica."},{"id":"UC16-FIS-T3-Q02","sp":1,"tus":["T3"],"prova":"T3 (2022/2) Q2","selo":"OF","tipo":"discursiva","tema":"Critérios do TDM","enun":"Liste cinco dos sintomas que devem estar presentes nos pacientes diagnosticados com transtorno depressivo maior . Nos sintomas que você indicar deverá incluir os dois sintomas que são obrigatórios para o diagnóstico, listando os mesmos com os números 1 e 2.","itens":[],"gab":"1. Tristeza (humor deprimido); 2. Anedonia; outros: aumento ou diminuição do apetite, alteração do sono (insônia ou hipersonia), amotivação, irritabilidade (resposta do aluno, com nota cheia).","com":"Os obrigatórios (pelo menos um deles) são humor deprimido e anedonia; os demais vêm da lista do DSM-5 (peso/apetite, sono, psicomotricidade, fadiga, culpa, concentração, ideação de morte)."},{"id":"UC16-FIS-T3-Q03","sp":1,"tus":["T3","T6"],"prova":"T3 (2022/2) Q3 · T6 (2024/1) Q11","selo":"OF","tipo":"direta","tema":"Transtornos de humor","enun":"Analise as seguintes afirmativas sobre transtornos de humor e assinale aquela que estiver incorreta:","itens":[],"alts":["A duração de um episódio depressivo não-tratado pode variar de algumas semanas a meses ou mesmo anos, ou ainda pode desaparecer de forma espontânea em cerca de 6 meses.","Insônia, cefaleia, dor, e distúrbios gastrointestinais são sintomas físicos associados a quadros de depressão.","O início do Transtorno disruptivo de desregulação do humor deve ser antes dos 10 anos, e o diagnóstico não deve ser aplicado a crianças com menos de 6 anos.","Pacientes com Transtorno depressivo persistente tem menor probabilidade de apresentar transtornos de ansiedade ou transtornos de personalidade borderline.","É possível aplicar o diagnóstico de transtorno depressivo maior àqueles que passaram pela perda de um ente querido há menos de dois anos"],"gab":"D","com":"O transtorno depressivo persistente tem MAIOR comorbidade com transtornos de ansiedade e personalidade borderline. O DSM-5 retirou a exclusão do luto, por isso E é correta."},{"id":"UC16-FIS-T3-Q04","sp":1,"tus":["T3"],"prova":"T3 (2022/2) Q4","selo":"OF","tipo":"discursiva","tema":"Causas clínicas de depressão","enun":"Liste 4 doenças clínicas que podem apresentar sintomas depressivos.","itens":[],"gab":"Hipotireoidismo; deficiência de vitamina B12/folato; anemia; feocromocitoma (resposta do aluno, corrigida com vistos).","com":"Outras aceitas na literatura: Cushing, Addison, Parkinson, AVC, esclerose múltipla, LES, câncer de pâncreas, HIV."},{"id":"UC16-FIS-T3-Q05","sp":4,"tus":["T3"],"prova":"T3 (2022/2) Q5","selo":"OF","tipo":"caso","tema":"Alucinação","enun":"Em entrevista com paciente, a mesma relata que precisou ser internada por motivo de ansiedade, tristeza profunda, crises de choro, medo e por escutar vozes de comando que interagiam com a paciente mandando-a cometer suicídio. A alteração de pensamento que pode ser detectada na paciente é:","itens":[],"alts":["incongruência afetiva","fuga de ideas","alucinação","delírio","discurso desorganizado"],"gab":"C","com":"Ouvir vozes de comando sem estímulo real é alucinação auditiva (rigorosamente, alteração da sensopercepção, não do pensamento: a pegadinha está no enunciado)."},{"id":"UC16-FIS-T3-Q06","sp":"","tus":["T3"],"prova":"T3 (2022/2) Q6","selo":"OF","tipo":"discursiva","tema":"Diagnóstico diferencial: esquizofrenia, bipolar e pânico","enun":"Explique em 5 linhas como você distinguiria, em uma unidade de saúde, um paciente com esquizofrenia, fazendo o diagnóstico diferencial com transtorno bipolar e com síndrome do pânico.","itens":[],"gab":"Esquizofrenia: sintomas positivos (alucinações e delírios) em surto psicótico. Transtorno bipolar: pode ter surto psicótico, mas há episódios de mania/hipomania e fases depressivas. Síndrome do pânico: sintomas físicos com pico em minutos que depois regridem (taquicardia, sudorese, calafrios, náusea/vômito, diarreia). (Resposta do aluno, nota cheia; o professor acrescentou na margem algo como 'sintomas negativos'.)","com":"Na esquizofrenia os sintomas psicóticos ocorrem fora de episódios de humor e há sintomas negativos; no bipolar a psicose aparece dentro dos episódios de humor; no pânico não há psicose."},{"id":"UC16-FIS-T3-Q07","sp":4,"tus":["T3"],"prova":"T3 (2022/2) Q7","selo":"OF","tipo":"sentenças","tema":"Esquizofrenia","enun":"Assinale as seguintes afirmativas sobre esquizofrenia e assinale abaixo a alternativa correta:","itens":["I. A catatonia é definida como um conjunto de movimentos, posturas e ações complexas cujo denominador comum é a sua involuntariedade.","II. Os sintomas psicóticos tendem a aumentar ao longo da vida, sendo mais frequentes quanto mais velho é o paciente.","III. A hiperativação da via mesolímbica dopaminérgica induz sintomas positivos de esquizofrenia através do aumento da estimulação de receptores D2 nas áreas límbicas.","IV. Acredita é que pacientes com esquizofrenia têm menos responsividade em receptores NMDA do glutamato, o que diminuiria a transmissão glutamatérgica.","V. Foi demonstrado que o consumo de canabinóides, não constitui um fator precipitante em indivíduos predispostos a apresentar esquizofrenia."],"alts":["I, II e V","I e III","I, III e IV","III e IV","I e V"],"gab":"C","com":"Sintomas psicóticos tendem a DIMINUIR com a idade (declínio dopaminérgico) e canabinoides SÃO fator precipitante; I, III e IV seguem o material (hipofunção NMDA)."},{"id":"UC16-FIS-T3-Q08","sp":3,"tus":["T3"],"prova":"T3 (2022/2) Q8","selo":"IN","tipo":"discursiva","tema":"TAG: critérios DSM-5","enun":"Paciente buscou atendimento no PA do hospital relatando que há 10 meses não está conseguindo concentração suficiente para estudar, está tenso e muito preocupado em relação às provas de residência que deverá prestar em dois anos, afirma ter sensações de \"branco\". Refere não estar conseguindo dormir bem, pois fica durante horas pensando em tudo que precisa fazer. Disse que tem lembrança de ter sido assim desde criança. Diagnóstico: transtorno de ansiedade generalizada. Explique que dados justificam o diagnóstico, fundamentando a sua resposta nos critérios da DSM-5. Indique também que outros sinais e sintomas você poderá perceber durante a anamnese, que possam validar o diagnótico. (use o verso da folha para a sua resposta)","itens":[],"gab":"Dados do caso que fecham TAG pelo DSM-5: (A) ansiedade e preocupação excessivas e desproporcionais (provas que só ocorrerão em dois anos), na maioria dos dias, há 10 meses (o critério exige pelo menos 6 meses); (B) dificuldade de controlar a preocupação (passa horas pensando em tudo o que precisa fazer); (C) pelo menos 3 de 6 sintomas — ele tem dificuldade de concentração/'brancos', tensão e perturbação do sono (insônia inicial); (D) prejuízo funcional (não consegue estudar). O curso crônico, 'desde criança', reforça o diagnóstico.<br>Outros achados a pesquisar na anamnese: os demais sintomas do critério C — inquietação ou sensação de estar 'com os nervos à flor da pele', fatigabilidade e irritabilidade —, além de dores musculares/cefaleia tensional, tremores, sudorese, palpitações, boca seca, náusea ou diarreia e sobressaltos; e afastar substância ou doença clínica (cafeína, estimulantes, hipertireoidismo) e outro transtorno mental que explique melhor o quadro (critérios E e F).","com":"A questão quer o cruzamento caso × critérios: duração de pelo menos 6 meses, preocupação excessiva e difícil de controlar, 3 ou mais dos 6 sintomas e prejuízo. A segunda parte pede os sintomas do critério C que o caso não citou e os sinais somáticos/autonômicos da ansiedade."},{"id":"UC16-FIS-T3-Q09","sp":3,"tus":["T3"],"prova":"T3 (2022/2) Q9","selo":"OF","tipo":"caso","tema":"Transtorno do pânico: sintomas","enun":"Paciente foi diagnosticada pela equipe médica com transtorno do pânico. Ela apresenta vários sintomas, mas é necessária a conjugação de pelo menos quatro sintomas para tal identificação, que podem ser: (assinale a melhor alternativa)","itens":[],"alts":["sudorese, cefaleia constante, e tremores, diarreia","palpitações, podipsia, polifagia e sudorese","sensação de asfixia taquicardia, sudorese, naúsea","taquicardia, ondas de calor, torpor, e amnésia","hiperatividade, tontura, dormência e desconforto torácico"],"gab":"C","com":"Asfixia, taquicardia, sudorese e náusea estão todos na lista do DSM-5 para ataque de pânico; cefaleia constante, polidipsia/polifagia, torpor, amnésia e hiperatividade não estão.","rep":2},{"id":"UC16-FIS-T3-Q10","sp":3,"tus":["T3"],"prova":"T3 (2022/2) Q10","selo":"OF","tipo":"sentenças","tema":"TAG","enun":"Paciente de 52, sexo masculino, refere que possui diagnóstico de transtorno da ansiedade generalizada há 15 anos. Sobre esse transtorno, pode-se afirmar que:","itens":["I. As pessoas não desenvolvem transtornos de ansiedade sem qualquer antecedente desencadeante identificável","II. Pessoas com crises de ansiedade podem apresentar dor torácica, cuja origem pode estar associada a um espasmo coronário, dentre outros fatores.","III. Muitos dos transtornos de ansiedade se desenvolvem na infância e tendem a persistir se não forem tratados.","IV. Os sintomas tendem a ser crônicos ,e há remissões e recidivas ao longo da vida, flutuando entre formas sindrômicas e subsindrômicas do transtorno.","V. Para o diagnóstico do transtorno de ansiedade generalizada, a ansiedade e a preocupação devem estar associados com outros três (ou mais) sintomas, pelo período mínimo de 3 meses."],"alts":["I, II e V","II, III e IV","III e IV","II e V","I, II e III"],"gab":"B","com":"I é falsa (a ansiedade pode surgir sem desencadeante) e V é falsa (o TAG exige 6 meses, não 3).","rep":2},{"id":"UC16-FIS-T3-Q11","sp":2,"tus":["T3"],"prova":"T3 (2022/2) Q11","selo":"OF","tipo":"discursiva","tema":"Transtorno bipolar","enun":"Assinale com V as afirmativas corretas e com F as incorretas:","itens":["( ) Para o diagnostico de transtorno bipolar tipo I é necessário pelo menos um episódio maníaco na vida, sem obrigatoriedade de quadro de psicose.","( ) A Hipomania não se apresenta com sintomas psicóticos, não precisa de internação e o prejuízo ao paciente não é tão intenso quanto no episódio de mania.","( ) O diagnóstico do transtorno bipolar tipo II requer um ou mais episódios depressivos maiores e pelo menos um episodio maníaco.","( ) O transtorno bipolar ciclotímico caracteriza-se por períodos maníacos e períodos de \"minidepressão\" que duram poucos dias e seguem um curso irregular.","( ) O risco de transtorno bipolar tipo II tende a ser mais elevado entre parentes de pessoas com essa condição, quando comparado com transtorno bipolar tipo I."],"gab":"Sequência: V, V, F, F, V","com":"O TB II exige episódio HIPOMANÍACO (não maníaco) e a ciclotimia tem períodos HIPOMANÍACOS; as demais são verdadeiras."},{"id":"UC16-FIS-T3-Q12","sp":2,"tus":["T3"],"prova":"T3 (2022/2) Q12","selo":"OF","tipo":"direta","tema":"Hipomania","enun":"Define-se como hipomania,","itens":[],"alts":["estado de ausência de interesse, no qual o paciente está insensível e indiferente.","perda da capacidade de sentir prazer.","período no qual o paciente cicla entre estado psicótico e depressivo.","exacerbação do humor, mas sem sintomas psicóticos.","perda da capacidade de cuidar de si, estando sujeito ao cuidado familiar."],"gab":"D","com":"Hipomania é elevação do humor mais branda que a mania, sem sintomas psicóticos e sem necessidade de internação; as outras definem apatia, anedonia e incapacidade."},{"id":"UC16-FIS-T3-Q13","sp":2,"tus":["T3"],"prova":"T3 (2022/2) Q13","selo":"OF","tipo":"sentenças","tema":"Transtorno bipolar","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar e assinale abaixo a alternativa correta:","itens":["I. Os Episódios Mistos geralmente evoluem a partir de um Episódio Maníaco.","II. No transtorno bipolar, os episódios maníacos e depressivos se alternam regularmente","III. O humor irritável é uma das manifestações depressivas mais comuns em crianças e adolescentes.","IV. As características psicóticas são mais comuns na depressão bipolar do que na depressão unipolar.","V. Algumas vezes, o paciente pode não apresentar sentimento de tristeza e concentrar suas queixas em dores e outras queixas físicas, tais como cefaleia, dor de estômago, dor no peito."],"alts":["I e III","III e IV","I, II e III","II e V","III, IV e V"],"gab":"E","com":"Os episódios NÃO se alternam regularmente, e os mistos podem surgir de episódio maníaco, depressivo ou do nada; III, IV e V são verdadeiras."},{"id":"UC16-FIS-T5-Q01","sp":2,"tus":["T5"],"prova":"T5 (2023/2) Q1","selo":"OF","tipo":"direta","tema":"Bipolar tipo II","enun":"Denomina-se transtorno bipolar tipo II, o transtorno em que acontece:","itens":[],"alts":["pelo menos um episódio de mania, que pode ter sido antecedido ou seguido por episódios depressivos maiores ou hipomaníacos","um episódio hipomaníaco seguido de episódio depressivo.","um ou mais episódios depressivos maiores e pelo menos um episodio hipomaníaco","um episódio hipomaníaco acompanhado por ideação suicida.","somente episódios hipomaníacos"],"gab":"C","com":"TB II = pelo menos um episódio depressivo maior e um hipomaníaco, sem nunca ter tido mania. A alternativa A define o tipo I.","rep":2},{"id":"UC16-FIS-T5-Q02","sp":1,"tus":["T5"],"prova":"T5 (2023/2) Q2","selo":"OF","tipo":"sentenças","tema":"Fisiopatologia da depressão","enun":"Analise as seguintes afirmativas sobre a depressão, e assinale abaixo a resposta correta:","itens":["I. No stress crônico associado à depressão, a ativação das vias inflamatórias pode se tornar menos sensível para o efeito inibitório do cortisol.","II. A diminuição da serotonina e o aumento do cortisol podem levar à infrarregulação BDNF e à supressão da neurogênese, o que pode explicar em parte a fisiopatologia da depressão.","III. O diagnostico do transtorno depressivo maior baseado em um único episodio é possível, embora o transtorno seja recorrente na maioria dos casos.","IV. No transtorno depressivo persistente, os sintomas tipicamente começam abrupamente durante a adolescência, mas podem persistir por muito anos.","V. A depressão pode ser incluída no grupo de doenças neurodegenerativas pelas alterações observadas na neurogênese desses pacientes."],"alts":["I, II e III","II, III e IV","I, III, IV e V","I e III","II, III e V"],"gab":"A","com":"O TDP começa de forma INSIDIOSA, e a depressão não é classificada como doença neurodegenerativa (a anotação de veterano sugere 'neurofuncional')."},{"id":"UC16-FIS-T5-Q03","sp":4,"tus":["T5"],"prova":"T5 (2023/2) Q3","selo":"VE","tipo":"direta","tema":"Esquizofrenia","enun":"Assinale a afirmativa incorreta sobre esquizofrenia:","itens":[],"alts":["Os sintomas psicóticos tendem a diminuir ao longo da vida, talvez pelo declínio normal na atividade dopaminérgica relacionada ao envelhecimento.","Alucinações auditivas, muitas vezes, são indícios de problemas neurológicos, clínicos ou associados a quadros de abstinência de substâncias.","A definição atual de esquizofrenia indica uma psicose crônica idiopática","Em geral, pacientes com esquizofrenia mantem a clareza de consciência e capacidade intelectual, e apresentam déficits cognitivos que podem evoluir com o tempo.","O Transtorno esquizoafetivo é diferenciado da esquizofrenia pela ocorrência de um ou mais episódios de depressão ou mania ao longo da vida de uma pessoa."],"gab":"B","com":"As alucinações AUDITIVAS são as mais comuns na esquizofrenia; as VISUAIS é que sugerem causa neurológica, clínica ou abstinência."},{"id":"UC16-FIS-T5-Q04","sp":1,"tus":["T5"],"prova":"T5 (2023/2) Q4","selo":"OF","tipo":"direta","tema":"Transtorno depressivo persistente","enun":"O transtorno psiquiátrico do adulto que é marcado pela presença de humor deprimido na maior parte do dia, na maioria dos dias, pelo período mínimo de dois anos, sem remissão é:","itens":[],"alts":["Transtorno Depressivo Maior","Ciclotimia.","Depressão Sazonal","Transtorno Depressivo Persistente","Transtorno Bipolar"],"gab":"D","com":"Humor deprimido crônico por ≥2 anos em adultos (1 ano em crianças) = transtorno depressivo persistente (distimia)."},{"id":"UC16-FIS-T5-Q05","sp":3,"tus":["T5","T10"],"prova":"T5 (2023/2) Q5 · T10 (2026/1) Q2","selo":"OF","tipo":"sentenças","tema":"TAG: neurobiologia","enun":"Paciente de 36 anos, sexo feminino, refere que possui diagnóstico de transtorno da ansiedade generalizada há 12 anos. Sobre esse transtorno, pode-se afirmar que:","itens":["I. O ataque de pânico pode ser considerado como patognomônico para o diagnóstico do transtorno de ansiedade generalizada.","II. No transtorno de ansiedade, a amigdala é considerada o ponto inicial das respostas corporais inerentes ao transtorno.","III. O efeito ansiolítico do GABA parece consistir em reduzir o funcionamento de grupos neuronais no córtex pré-frontal e no hipocampo.","IV. A serotonina 5-HT exerce um duplo papel na regulação da ansiedade, sendo ansiogênica na amígdala e ansiolítica na matéria cinzenta periaquedutal dorsal (MCPD).","V. Sugere-se que causas cardíacas, como espasmos coronários ou isquemia, ou não cardíacas podem estar presentes em pacientes com dor torácica nas crises de ansiedade."],"alts":["I, II e IV","II, IV e V","I e III","II, III e IV","III, IV e V"],"gab":"B","com":"Ataque de pânico não é patognomônico de TAG, e o GABA age no sistema límbico (amígdala), não no 'córtex pré-frontal e hipocampo' (correção anotada na cópia p8)."},{"id":"UC16-FIS-T5-Q06","sp":2,"tus":["T5"],"prova":"T5 (2023/2) Q6","selo":"OF","tipo":"direta","tema":"Hipomania","enun":"Define-se como hipomania,","itens":[],"alts":["período no qual o paciente cicla entre estado psicótico e depressivo.","exacerbação do humor, mas sem sintomas psicóticos.","estado de ausência de interesse, no qual o paciente está insensível e indiferente.","perda da capacidade de sentir prazer.","perda da capacidade de cuidar de si, estando sujeito ao cuidado familiar."],"gab":"B","com":"Hipomania: elevação do humor sem psicose e sem prejuízo grave. As anotações de veterano lembram que C e D descrevem depressão (apatia, anedonia)."},{"id":"UC16-FIS-T5-Q07","sp":1,"tus":["T5"],"prova":"T5 (2023/2) Q7","selo":"OF","tipo":"caso","tema":"Transtorno depressivo maior","enun":"Paciente do sexo masculino, 24 anos, apresenta há 3 meses irritabilidade, insônia, e diminuição do apetite. Refere não tem conseguido fazer as atividades de que antes gostava. Relata maior indisposição para o trabalho, o que tem gerado alguma dificuldade com os colegas. Refere episódio semelhante há 4 anos. O diagnóstico possível neste caso seria:","itens":[],"alts":["Transtorno depressivo maior","Síndrome do pânico","Transtorno bipolar","Transtorno depressivo persistente","Transtorno de ansiedade"],"gab":"A","com":"Mais de 2 semanas com anedonia e 5 sintomas = episódio depressivo maior (recorrente). Três meses não bastam para TDP (2 anos).","rep":3},{"id":"UC16-FIS-T5-Q08","sp":2,"tus":["T5"],"prova":"T5 (2023/2) Q8","selo":"OF","tipo":"sentenças","tema":"Transtorno bipolar","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar e assinale abaixo a alternativa correta:","itens":["I. Substancias de abuso como álcool e cocaína, e alguns medicamentos prescritos podem estar associados a um fenômeno semelhante ao episódio maníaco.","II. Os episódios maníacos e depressivos se alternam regularmente, podendo haver a sequência de um episódio maníaco, depois um depressivo e assim por diante.","III. Podem ocorrer sintomas depressivos durante um episódio maníaco e, quando presentes, durar momentos, horas ou, mais raramente, dias.","IV. Estudos realizados com gêmeos, permitem estimar uma taxa de hereditariedade menor que 25% no transtorno afetivo bipolar.","V. Um Episódio Misto caracteriza-se por um período de tempo, de no mínimo 1 semana, durante o qual são satisfeitos os critérios tanto para Episódio Maníaco quanto para Episódio Depressivo Maior, quase todos os dias."],"alts":["I, II e III","I, III e V","II, IV e V","I e III","III e IV"],"gab":"B","com":"Os episódios não se alternam regularmente, e a herdabilidade estimada em gêmeos é alta (~60-85%), não menor que 25%."},{"id":"UC16-FIS-T5-Q09","sp":1,"tus":["T5"],"prova":"T5 (2023/2) Q9","selo":"OF","tipo":"direta","tema":"TDDH","enun":"Qual dos transtornos de humor listados abaixo é o único cujos sintomas surgem obrigatoriamente durante a infância?","itens":[],"alts":["Transtorno depressivo maior.","Transtorno afetivo bipolar.","Distimia.","Transtorno disruptivo de desregulação do humor.","Transtorno ciclotímico"],"gab":"D","com":"O TDDH exige início antes dos 10 anos (diagnóstico entre 6 e 18 anos). Os demais podem começar em qualquer idade."},{"id":"UC16-FIS-T5-Q10","sp":4,"tus":["T5"],"prova":"T5 (2023/2) Q10","selo":"OF","tipo":"discursiva","tema":"Esquizofrenia","enun":"Assinale com V as afirmativas corretas e com F as afirmativas incorretas sobre a esquizofrenia:","itens":["( ) As características psicóticas da esquizofrenia surgem principalmente na infância ou inicio da adolescência.","( ) Os transtornos esquizofrênicos são caracterizados pelo embotamento afetivo, um efeito de indiferença, falta de afeto e incapacidade de sentir emoções.","( ) Na esquizofrenia, a estimulação excessiva da via dopaminérgica mesocortical provocaria a liberação excessiva de dopamina no córtex e o aparecimento dos sinais negativos.","( ) A catatonia é definida como um conjunto de movimentos, posturas e ações complexas cujo denominador comum é a sua involuntariedade.","( ) Foi demonstrado que o consumo de canabinóides não constitui um fator precipitante em indivíduos predispostos a apresentar esquizofrenia."],"gab":"Sequência: F, V, F, V, F","com":"A psicose surge tipicamente no fim da adolescência ou início da vida adulta, os sinais negativos vêm da HIPOatividade mesocortical, e canabinoides são precipitantes."},{"id":"UC16-FIS-T5-Q11a","sp":1,"tus":["T5","T6"],"prova":"T5 (2023/2) Q11a · T6 (2024/1) Q13a","selo":"OF","tipo":"discursiva","tema":"TDDH: diagnóstico","enun":"Explique nas linhas destinadas à resposta, como você distinguiria em uma unidade de saúde os seguintes quadros (considere os sinais patognomônicos): A. Um paciente com transtorno disruptivo de desregulação do humor","itens":[],"gab":"Início antes dos 10 anos (diagnóstico entre 6/7 e 18 anos); irritabilidade/raiva persistente na maior parte do dia, quase todos os dias; explosões de raiva graves e desproporcionais, em média ≥3 vezes por semana (respostas de dois alunos, com nota parcial).","com":"O patognomônico do TDDH é a irritabilidade crônica entre as explosões de raiva recorrentes, com início antes dos 10 anos."},{"id":"UC16-FIS-T6-Q13b","sp":3,"tus":["T5","T6"],"prova":"T5 (2023/2) Q11b · T6 (2024/1) Q13b","selo":"OF","tipo":"discursiva","tema":"Transtorno de pânico: diagnóstico","enun":"Explique nas linhas destinadas à resposta, como você distinguiria em uma unidade de saúde os seguintes quadros (considere os sinais patognomônicos): B. Um paciente com síndrome do pânico.","itens":[],"gab":"Ataques súbitos com sensação de perigo iminente/medo de morrer e sintomas físicos (falta de ar, taquicardia, sudorese, tremor, dor no peito, sensação de desmaio), com pico em minutos (respostas de alunos; em uma delas o professor anotou 'histórico').","com":"Ataques inesperados e recorrentes, com pico em minutos, seguidos de preocupação persistente com novos ataques ou de evitação."},{"id":"UC16-FIS-T5-Q12","sp":3,"tus":["T5"],"prova":"T5 (2023/2) Q12","selo":"VE","tipo":"discursiva","tema":"Cortisol e ansiedade","enun":"Explique (em 4 linhas) qual á a relação da alteração dos níveis de cortisol com a fisiopatogênia dos transtornos de ansiedade.","itens":[],"gab":"No transtorno de ansiedade a amígdala ativa o hipotálamo, que ativa o eixo HHA; os níveis elevados de cortisol levam a injúria tecidual e podem danificar neurônios do hipocampo, de modo que o controle por feedback do eixo HHA é prejudicado, havendo contínua liberação de cortisol e catecolaminas (texto digitado por veterano; resposta semelhante de aluno recebeu nota parcial).","com":"O estresse crônico mantém o cortisol alto, que lesa o hipocampo (que normalmente freia o eixo HHA) e cria um ciclo vicioso de hiperativação."},{"id":"UC16-FIS-T6-Q01","sp":3,"tus":["T6"],"prova":"T6 (2024/1) Q1","selo":"OF","tipo":"caso","tema":"Transtorno do pânico: sintomas","enun":"Paciente de 48 anos, sexo feminino, foi diagnosticada pela equipe médica com transtorno do pânico. Ela apresenta vários sintomas, mas é necessária a conjugação de pelo menos quatro sintomas para tal identificação, que devem incluir","itens":[],"alts":["taquicardia, ondas de calor, torpor, e amnésia","sudorese, cefaleia constante, e tremores","palpitações, podipsia, polifagia e palpitações","sensação de asfixia, taquicardia, sudorese, naúsea","hiperatividade, tontura, dormência e desconforto torácico"],"gab":"D","com":"Asfixia, taquicardia, sudorese e náusea estão na lista do DSM-5. Torpor, amnésia, cefaleia constante, polidipsia/polifagia e hiperatividade não estão.","rep":2},{"id":"UC16-FIS-T6-Q02","sp":2,"tus":["T6"],"prova":"T6 (2024/1) Q2","selo":"OF","tipo":"direta","tema":"Bipolar tipo I","enun":"Denomina-se transtorno bipolar tipo I, o transtorno em que acontece:","itens":[],"alts":["um ou mais episódios depressivos maiores e pelo menos um episodio hipomaníaco","pelo menos um episódio de mania, que pode ter sido antecedido ou seguido por episódios depressivos maiores ou hipomaníacos","um episódio hipomaníaco seguido de episódio depressivo.","um episódio hipomaníaco acompanhado por ideação suicida.","somente episódios hipomaníacos"],"gab":"B","com":"TB I exige pelo menos um episódio maníaco; depressão e hipomania podem ou não ocorrer. A alternativa A define o tipo II.","rep":2},{"id":"UC16-FIS-T6-Q03","sp":1,"tus":["T6"],"prova":"T6 (2024/1) Q3","selo":"OF","tipo":"sentenças","tema":"Depressão","enun":"Analise as seguintes afirmativas sobre a depressão e assinale abaixo a alternativa correta:","itens":["I. O diagnostico do transtorno depressivo maior baseado em um único episodio é possível, embora o transtorno seja recorrente na maioria dos casos.","II. No transtorno depressivo persistente, o número de sintomas muitas vezes oscila acima e abaixo do limiar para episódio depressivo maior, mas devem durar pelo menos 1 ano.","III. Em quadros de depressão, a o NF-k pode contribuir com a diminuição de monoaminas como a serotonina e o aumento de fatores tróficos como o BNDF.","IV. O Transtorno Disruptivo de Desregulação do Humor é um quadro de maior incidência em mulheres, sobretudo após a menopausa","V. Sugere-se que na depressão, a secreção excessiva e prolongada de cortisol pode levar à supressão da neurogênese e atrofia de estruturas límbicas"],"alts":["I, II e III","I, III e V","II, IV e V","II e IV","I e V"],"gab":"E","com":"No adulto o TDP exige 2 anos, o NF-kB DIMINUI o BDNF, e o TDDH é um transtorno da infância."},{"id":"UC16-FIS-T6-Q04","sp":2,"tus":["T6"],"prova":"T6 (2024/1) Q4","selo":"OF","tipo":"direta","tema":"Transtorno bipolar","enun":"Assinale a afirmativa incorreta sobre o transtorno bipolar","itens":[],"alts":["Os Episódios Mistos podem evoluir a partir de um Episódio Maníaco ou de um Episódio Depressivo Maior ou podem surgir como algo novo.","As características psicóticas são mais comuns na depressão bipolar do que na depressão unipolar.","O humor irritável é uma das manifestações depressivas mais comuns em crianças e adolescentes.","No transtorno bipolar, os episódios maníacos e depressivos se alternam regularmente.","Ambas as fases de mania e depressão podem ocorrer alternadamente porém em alguns pacientes só uma das fases se manifesta com mais frequência."],"gab":"D","com":"Os episódios NÃO se alternam regularmente: é a pegadinha recorrente desta professora."},{"id":"UC16-FIS-T6-Q05","sp":4,"tus":["T6"],"prova":"T6 (2024/1) Q5","selo":"OF","tipo":"sentenças","tema":"Esquizofrenia","enun":"Assinale as seguintes afirmativas sobre esquizofrenia e assinale abaixo a alternativa correta:","itens":["I. Agonistas de do receptor 5-HT2A aumentam a liberação de dopamina, o que pode fundamentar a hipótese de alterações serotoninérgicas na gênese dos sintomas positivos da esquizofrenia.","II. A catatonia é definida como um conjunto de movimentos, posturas e ações complexas cujo denominador comum é a sua involuntariedade.","III. Acredita-se que em pacientes com esquizofrenia têm maior responsividade em receptores NMDA o que poderia explicar a ocorrência dos sintomas negativos.","IV. Os sintomas psicóticos tendem a aumentar ao longo da vida, sendo mais frequentes quanto mais velho é o paciente.","V. O aumento da expressão gabaergica e diminuição da transmissão gabaérgica estariam associados ao aparecimento tanto dos sintoma positivos quanto dos sintomas negativos na esquizofrenia."],"alts":["I, II e III","II, III e V","I, II e IV","II, III e IV","I e II"],"gab":"E","com":"A hipótese é de MENOR responsividade NMDA, os sintomas psicóticos diminuem com a idade, e V é contraditória (aumento da expressão e diminuição da transmissão gabaérgica)."},{"id":"UC16-FIS-T6-Q06","sp":3,"tus":["T6"],"prova":"T6 (2024/1) Q6","selo":"OF","tipo":"direta","tema":"TAG","enun":"Paciente do sexo masculino, refere que possui diagnóstico de transtorno da ansiedade generalizada há 10 anos. Sobre esse transtorno, pode-se afirmar que:","itens":[],"alts":["Os ataques de pânico considerados clássicos estão limitados aos transtornos de ansiedade.","As pessoas não desenvolvem transtornos de ansiedade se não houver qualquer antecedente desencadeante identificável","Pessoas com crises de ansiedade podem apresentar dor torácica, cuja origem deve estar associada a um espasmo coronário pela excessiva liberação de adrenalina.","Os sintomas tendem a ser crônicos ,e há remissões e recidivas ao longo da vida, flutuando entre formas sindrômicas e subsindrômicas do transtorno.","Para o diagnóstico do transtorno de ansiedade generalizada, a ansiedade e a preocupação devem estar associados com outros três (ou mais) sintomas, pelo período mínimo de 3 meses."],"gab":"D","com":"Ataques de pânico ocorrem em vários transtornos, a ansiedade pode surgir sem desencadeante, a dor torácica não 'deve' ser coronariana, e o TAG exige 6 meses.","rep":2},{"id":"UC16-FIS-T6-Q07","sp":1,"tus":["T6"],"prova":"T6 (2024/1) Q7","selo":"OF","tipo":"caso","tema":"Transtorno depressivo maior","enun":"Paciente do sexo masculino, 19 anos, apresenta há 3 meses irritabilidade, insônia, e diminuição do apetite. Refere não ter vontade de fazer as atividades de que antes gostava. Relata maior indisposição para o trabalho, o que tem gerado alguma dificuldade com os colegas. Refere episódio semelhante há 4 anos. O diagnóstico possível neste caso seria:","itens":[],"alts":["Transtorno depressivo maior","Síndrome do pânico.","Transtorno bipolar","Transtorno depressivo persistente","Transtorno de ansiedade"],"gab":"A","com":"Anedonia com sintomas há mais de 2 semanas e episódio prévio = TDM recorrente. Três meses não bastam para TDP.","rep":3},{"id":"UC16-FIS-T6-Q08","sp":4,"tus":["T6"],"prova":"T6 (2024/1) Q8","selo":"VE","tipo":"sentenças","tema":"Esquizofrenia: vias dopaminérgicas","enun":"Analise as seguintes afirmativas sobre a esquizofrenia e assinale abaixo a alternativa correta:","itens":["I. A Hiperatividade dopaminérgica na via mesolimbica seria responsável pelos sintomas positivos da esquizofrenia.","II. Alucinações auditivas, são as mais comuns na esquizofrenia, enquanto que as visuais podem indicar também problemas neurológicos, clínicos ou associados a quadros de abstinência de substâncias.","III. A hipoativação da via mesocortical dopaminérgica causa sintomas negativos e cognitivos de esquizofrenia via diminuição da ativação de receptores D1 nas áreas corticais.","IV. A definição atual de esquizofrenia indica uma psicose crônica por alterações neuroquímicas.","V. O antagonismo dopaminérgico na via mesocortical induz efeitos extrapiramidais."],"alts":["I, II, III e V","I, III, e V","I e III","II, III e IV","Todas as alternativas estão corretas."],"gab":"C","com":"A definição atual é de psicose crônica IDIOPÁTICA, e os efeitos extrapiramidais vêm da via NIGROESTRIATAL. Pela professora, II também foi considerada errada."},{"id":"UC16-FIS-T6-Q09","sp":3,"tus":["T6"],"prova":"T6 (2024/1) Q9","selo":"VE","tipo":"direta","tema":"Neurobiologia da ansiedade","enun":"Assinale a afirmativa incorreta sobre o transtorno de ansiedade:","itens":[],"alts":["A serotonina 5-HT tem participação na regulação da ansiedade, exercendo um papel ansiogênico na amígdala e ansiolítico quanto na matéria cinzenta periaqueductal dorsal.","A relação entre o GABA e a ansiedade evidencia-se no fato de que todos os ansiolíticos conhecidos, facilitam sua ação.","No stress associado à ansiedade há injúria dos interneurônios inibitórios de modo que neurônios excitatórios da amígdala ficam em estado de hiperexcitabilidade.","A exposição contínua ao cortisol, em períodos de estresse crônico, pode levar à disfunção e à morte dos neurônios hipocampais e ao aparecimento dos sintomas caraterísticos do quadro.","O efeito ansiolítico do GABA parece consistir em reduzir o funcionamento de grupos neuronais do córtex cerebral."],"gab":"E","com":"Pelo material, o GABA reduz o funcionamento de grupos neuronais do SISTEMA LÍMBICO (amígdala e hipocampo), não do córtex cerebral."},{"id":"UC16-FIS-T6-Q10","sp":4,"tus":["T6"],"prova":"T6 (2024/1) Q10","selo":"VE","tipo":"caso","tema":"Alteração do pensamento","enun":"Paciente atendido no CAPES não soube relatar uma queixa principal concisa, dizendo que estava \"preso no poder divino há 7 anos\" e que \"as deusas não entregam o seu ser\", contando vários relatos de conteúdo místico, e contado ainda sobre a viagem que faria para o polo norte. O sintoma que pode ser detectado no paciente é:","itens":[],"alts":["delírio","incongruência afetiva","discurso desorganizado","comportamento desorganizado","alucinação"],"gab":"A","com":"As crenças de conteúdo místico e grandioso, mantidas com convicção, são delírio.","rep":2},{"id":"UC16-FIS-T6-Q12","sp":2,"tus":["T6"],"prova":"T6 (2024/1) Q12","selo":"OF","tipo":"discursiva","tema":"Transtorno bipolar","enun":"Assinale com V as afirmativas corretas e com F as incorretas:","itens":["( ) O risco de transtorno bipolar tipo II tende a ser mais elevado entre parentes de pessoas com essa condição, quando comparado com transtorno bipolar tipo I.","( ) Para o diagnostico de transtorno bipolar tipo II é necessário pelo menos um episódio maníaco na vida, sem obrigatoriedade de quadro de psicose.","( ) A Hipomania pode se apresentar com sintomas psicóticos, mas não precisa de internação, e o prejuízo ao paciente não é tão intenso quanto no episódio de mania.","( ) O diagnóstico do transtorno bipolar tipo II requer um ou mais episódios depressivos maiores e pelo menos um episodio maníaco.","( ) O transtorno bipolar ciclotímico caracteriza-se por períodos maníacos e períodos de \"minidepressão\" que duram poucos dias e seguem um curso irregular."],"gab":"Sequência: V, F, F, F, F","com":"Mania define o tipo I (não o II), a hipomania não tem sintomas psicóticos, e a ciclotimia tem períodos HIPOmaníacos."},{"id":"UC16-FIS-T7-Q01","sp":1,"tus":["T7"],"prova":"T7 (2024/2) Q1","selo":"OF","tipo":"caso","tema":"Transtorno depressivo maior","enun":"Paciente do sexo masculino, 19 anos, apresenta há 4 semanas insônia e diminuição do apetite. Refere uma sensação de tristeza constante e a falta de interesse ou prazer em atividades previamente recompensadoras ou agradáveis. Relata também maior indisposição para o trabalho. Refere episódio semelhante há 2 anos. O diagnóstico possível neste caso seria:","itens":[],"alts":["Transtorno depressivo maior","Síndrome do pânico.","Transtorno bipolar","Transtorno depressivo persistente","Transtorno de ansiedade"],"gab":"A","com":"Quatro semanas de humor deprimido, anedonia, insônia, hiporexia e fadiga = episódio depressivo maior. O episódio 'há 2 anos' não faz dele um TDP.","rep":3},{"id":"UC16-FIS-T7-Q02","sp":4,"tus":["T7"],"prova":"T7 (2024/2) Q2","selo":"VE","tipo":"direta","tema":"Esquizofrenia: critérios","enun":"Assinale a afirmativa incorreta sobre esquizofrenia:","itens":[],"alts":["Os sintomas psicóticos tendem a diminuir ao longo da vida, talvez pelo declínio normal na atividade dopaminérgica relacionada ao envelhecimento.","Para o diagnóstico da esquizofrenia, as manifestações que devem estar presentes (pelo menos uma das três) durante parte significativa do tempo em um mês ou mais são: delírios, alucinações, e sintomas negativos","Em geral, pacientes com esquizofrenia mantem a clareza de consciência e capacidade intelectual, mas apresentam déficits cognitivos que podem evoluir com o tempo.","Sintomas positivos são os sintomas que se apresentam durante os episódios de psicoses.","A catatonia é definida como um conjunto de movimentos, posturas e ações complexas cujo denominador comum é a sua involuntariedade."],"gab":"B","com":"Pelo DSM-5, pelo menos um dos sintomas obrigatórios é delírio, alucinação ou DISCURSO DESORGANIZADO; sintomas negativos não entram nesse trio."},{"id":"UC16-FIS-T7-Q03","sp":1,"tus":["T7"],"prova":"T7 (2024/2) Q3","selo":"OF","tipo":"sentenças","tema":"Depressão","enun":"Analise as seguintes afirmativas sobre a depressão e assinale abaixo a alternativa correta:","itens":["I. O diagnostico do transtorno depressivo maior baseado em um único episodio é possível, embora o transtorno seja recorrente na maioria dos casos.","II. Os sintomas do transtorno depressivo persistente tipicamente começam de forma insidiosa durante a adolescência e podem persistir por muito anos ou décadas","III. O transtorno depressivo maior é caracterizado por episódios distintos de pelo menos duas semanas de duração.","IV. No transtorno depressivo persistente, o número de sintomas muitas vezes oscila acima e abaixo do limiar para episódio depressivo maior, mas devem durar pelo menos 1 ano.","V. Segundo o DSM-5, não é possível aplicar o diagnóstico de depressão àqueles que passaram pela perda de um ente querido há menos de dois anos."],"alts":["I, II e III","I, III e V","I e III","II, IV e V","II e IV"],"gab":"A","com":"No adulto o TDP exige 2 anos (não 1), e o DSM-5 PERMITE diagnosticar depressão no luto."},{"id":"UC16-FIS-T7-Q04","sp":2,"tus":["T7"],"prova":"T7 (2024/2) Q4","selo":"OF","tipo":"direta","tema":"Mania x hipomania","enun":"São manifestações clinicas da mania, que distinguem de um episódio de hipomania:","itens":[],"alts":["Autoestima inflada ou grandiosidade, a perturbação do humor é grave a ponto de causar prejuízo acentuado no funcionamento social.","Estado de ausência de interesse, no qual o paciente está insensível e indiferente.","Período no qual o paciente alterna entre estado psicótico e depressivo.","Mais loquacidade que o habitual, redução da necessidade de sono.","Perda da capacidade de cuidar de si, estando sujeito ao cuidado familiar"],"gab":"A","com":"O que separa mania de hipomania é a gravidade: prejuízo acentuado, internação ou psicose. Loquacidade e pouco sono ocorrem nas duas."},{"id":"UC16-FIS-T7-Q05","sp":4,"tus":["T7"],"prova":"T7 (2024/2) Q5","selo":"VE","tipo":"sentenças","tema":"Esquizofrenia: fisiopatologia","enun":"Assinale com V as afirmativas corretas e com F as afirmativas incorretas sobre esquizofrenia:","itens":["I. A liberação reduzida de dopamina no córtex levaria ao aumento da atividade de neurônios glutamatérgicos que se projetam para o mesencéfalo. Por sua vez, neurônios do mesencéfalo aumentariam a liberação de dopamina no estriado.","II. Foi demonstrado que o consumo de canabinóides, não constitui um fator precipitante em indivíduos predispostos a apresentar esquizofrenia.","III. Na esquizofrenia, os astrócitos podem estar envolvidos com uma alteração na espessura dos vasos do cérebro, levando diminuição no fluxo metabólico em certas regiões cerebrais e portanto à neurodegeneração.","IV. Acredita-se que pacientes com esquizofrenia têm menos responsividade em receptores NMDA do glutamato, o que diminuiria a transmissão glutamatérgica na área mesocortical, o que levaria aos sintomas negativos.","V. O efeito mais seletivo dos antipsicóticos atípicos sobre os receptores D2 colaboraria para a menor probabilidade da ocorrência de sintomas extrapiramidais, que são comuns aos antipsicóticos típicos."],"alts":["I, II e III","I, III e IV","I, IV e V","III e IV","III e V"],"gab":"B","com":"Canabinoides são fator precipitante. Os atípicos têm menos efeito extrapiramidal por serem MENOS seletivos para D2 (bloqueiam também 5-HT2A, com dissociação rápida de D2)."},{"id":"UC16-FIS-T7-Q06","sp":2,"tus":["T7"],"prova":"T7 (2024/2) Q6","selo":"OF","tipo":"caso","tema":"Ciclotimia","enun":"Paciente do sexo feminino, 15 anos, apresenta há 14 meses um transtorno psiquiátrico que é marcado por vários períodos hipomaníacos e vários períodos de depressão que duram poucos dias, e seguem um curso irregular. O paciente não ficou sem os sintomas mais que dois meses consecutivos. Qual seria o seu diagnóstico?","itens":[],"alts":["Transtorno Depressivo Maior.","Depressão Sazonal","Ciclotimia.","Transtorno Bipolar:","Transtorno Depressivo Persistente"],"gab":"C","com":"Em crianças e adolescentes a ciclotimia exige só 1 ano de sintomas (2 anos no adulto); por isso 14 meses bastam."},{"id":"UC16-FIS-T7-Q07","sp":1,"tus":["T7"],"prova":"T7 (2024/2) Q7","selo":"OF","tipo":"direta","tema":"Fisiopatologia da depressão","enun":"As seguintes afirmativas sobre a depressão estão corretas, exceto:","itens":[],"alts":["A hipótese neurotrófica associa a diminuição da expressão de BDNF e atrofia de estruturas límbicas com a depressão.","Sugere-se que na depressão, a secreção excessiva e prolongada de cortisol pode levar à supressão da neurogênese e atrofia de estruturas límbicas","Na depressão, citocinas pro inflamatórias podem alcançar o cérebro e induzir vias de sinalização inflamatória, incluindo a do NF-kB , contribuindo para o metabolismo alterado de monoaminas.","O aumento da liberação de cortisol e a redução de estrógenos, que levam à diminuição da expressão de BDNF, são relacionados com a gênese da depressão pós parto.","No stress crônico, a ativação das vias inflamatórias pode se tornar mais sensível para o efeito inibitório do cortisol."],"gab":"E","com":"No estresse crônico as vias inflamatórias ficam MENOS sensíveis ao cortisol (resistência a glicocorticoide)."},{"id":"UC16-FIS-T7-Q08","sp":3,"tus":["T7"],"prova":"T7 (2024/2) Q8","selo":"OF","tipo":"caso","tema":"Transtorno do pânico: sintomas","enun":"Paciente de 39 anos, sexo feminino, foi diagnosticada pela equipe médica com transtorno do pânico. É necessária a conjugação de pelo menos quatro sintomas para tal identificação, que devem incluir:","itens":[],"alts":["hiperatividade motora, amnésia, tontura, tremores","sudorese, cefaleia constante, tremores e bradicardia","taquicardia, ondas de calor, torpor, e amnésia","sensação de tontura, polidipsia, polifagia, parestesias","sensação de asfixia, taquicardia, sudorese, naúsea"],"gab":"E","com":"Só a E tem os quatro itens da lista do DSM-5; as demais misturam amnésia, torpor, bradicardia, cefaleia, polidipsia e polifagia."},{"id":"UC16-FIS-T7-Q09","sp":1,"tus":["T7"],"prova":"T7 (2024/2) Q9","selo":"OF","tipo":"direta","tema":"TDDH","enun":"Assinale a afirmativa incorreta sobre o Transtorno Disruptivo de Regulação do humor:","itens":[],"alts":["Humor deprimido e isolamento estão presentes entre as explosões de raiva.","A característica central desse distúrbio é a irritabilidade crônica grave que pode manifestar-se com frequentes explosões de raiva, verbais ou comportamentais.","É um transtorno observado em crianças e adolescentes.","O início do transtorno deve ser antes dos 10 anos, e o diagnóstico não deve ser aplicado a crianças com menos de 6 anos.","Como os sintomas do transtorno provavelmente se modificam à medida que a criança cresce, o uso do diagnóstico deve ser restringido a faixas etárias similares àquelas em que a validade foi estabelecida ou seja, dos 7 a 18 anos."],"gab":"A","com":"Entre as explosões o humor é persistentemente IRRITÁVEL ou zangado, não deprimido com isolamento."},{"id":"UC16-FIS-T7-Q10","sp":2,"tus":["T7"],"prova":"T7 (2024/2) Q10","selo":"OF","tipo":"direta","tema":"Bipolar tipo I","enun":"Denomina-se transtorno bipolar tipo I, o transtorno em que acontece:","itens":[],"alts":["um ou mais episódios depressivos maiores e pelo menos um episodio hipomaníaco","pelo menos um episódio de mania, que pode ter sido antecedido ou seguido por episódios depressivos maiores ou hipomaníacos que duram pelo menos duas semanas.","pelo menos um episódio hipomaníaco seguido de episódio depressivo.","pelo menos um episodio hipomaníaco, de no mínimo 4 dias, durante o curso da vida, mas jamais um episódio maníaco.","somente episódios hipomaníacos"],"gab":"B","com":"Basta um episódio maníaco para o TB I. A e D descrevem o tipo II.","rep":2},{"id":"UC16-FIS-T7-Q11","sp":2,"tus":["T7"],"prova":"T7 (2024/2) Q11","selo":"VE","tipo":"caso","tema":"Episódio maníaco","enun":"Um estudante universitário de 24 anos de idade é trazido pelos seus familiares ao pronto-socorro. Há dois dias começou a falar que descobriu a cura para a covid-19, tendo enviado várias mensagens eletrônicas para diferentes jornais, instituições públicas e embaixadas. Diz agora que aguarda a ligação de ministros da saúde de vários países para conversar sobre sua descoberta. Quando questionado pelo irmão sobre esses fatos, ficou muito irritado e tentou agredi-lo fisicamente. A família diz que o paciente sempre foi estudioso, trabalhador, carinhoso com os pais e é amigo do irmão. Aos 20 anos de idade, apresentou quadro depressivo e foi tratado com medicamento, cujo nome os familiares não se recordam. Não há antecedentes familiares mórbidos relevantes. Qual é a principal hipótese diagnóstica neste quadro?","itens":[],"alts":["Esquizofrenia","Transtorno de ansiedade generalizada","Transtorno bipolar","Transtorno depressivo maior.","Transtorno Ciclotímico"],"gab":"C","com":"Grandiosidade com delírio, irritabilidade e agressividade em quem teve depressão tratada (possível virada maníaca) apontam para TB. Dois dias de psicose não fecham esquizofrenia."},{"id":"UC16-FIS-T7-Q12","sp":4,"tus":["T7"],"prova":"T7 (2024/2) Q12","selo":"OF","tipo":"discursiva","tema":"Esquizofrenia","enun":"Assinale com V as afirmativas corretas e com F as incorretas:","itens":["( ) Alucinações visuais, são as mais comuns na esquizofrenia, enquanto que as auditivas podem indicar também problemas neurológicos, clínicos ou associados a quadros de abstinência de substâncias.","( ) A hipoativação da via mesocortical dopaminérgica causaria sintomas negativos e cognitivos de esquizofrenia.","( ) A Hiperatividade dopaminérgica na via mesolimbica via receptores D1 seria responsável pelos sintomas positivos da esquizofrenia.","( ) A definição atual de esquizofrenia indica uma psicose crônica por alterações neuroquímicas.","( ) O antagonismo dopaminérgico pode levar estes pacientes à galactorreia, uma vez que a dopamina aumenta a produção de prolactina."],"gab":"Sequência: F, V, F, F, F","com":"As auditivas é que são mais comuns, os sintomas positivos vêm do receptor D2, a definição atual é de psicose IDIOPÁTICA, e a dopamina INIBE a prolactina."},{"id":"UC16-FIS-T7-Q13a","sp":3,"tus":["T7"],"prova":"T7 (2024/2) Q13a","selo":"OF","tipo":"discursiva","tema":"TAG: critérios","enun":"Paciente buscou atendimento no PA do hospital relatando que há 10 meses não está conseguindo concentração suficiente para estudar, está tenso e muito preocupado em relação às provas de residência que deverá prestar em quatro anos, a sua vida futura, e as obrigações diárias. Refere não estar conseguindo dormir bem, pois fica durante horas pensando em tudo que precisa fazer. Disse que tem lembrança de ter sido assim desde criança. Diagnóstico: transtorno de ansiedade Responda: A. Explique quis dos dados apresentados justificam o diagnóstico.","itens":[],"gab":"Preocupação excessiva com a vida futura, com impactos como insônia, ruminação de pensamentos e tensão; sintomas há mais de 6 meses (resposta do aluno, nota parcial).","com":"TAG: ansiedade e preocupação excessivas, difíceis de controlar, na maioria dos dias por ≥6 meses, com ≥3 sintomas (tensão muscular, insônia, dificuldade de concentração, fadiga, irritabilidade, inquietação)."},{"id":"UC16-FIS-T7-Q13b","sp":3,"tus":["T7"],"prova":"T7 (2024/2) Q13b","selo":"VE","tipo":"discursiva","tema":"TAG: fisiopatologia","enun":"Paciente buscou atendimento no PA do hospital relatando que há 10 meses não está conseguindo concentração suficiente para estudar, está tenso e muito preocupado em relação às provas de residência que deverá prestar em quatro anos, a sua vida futura, e as obrigações diárias. Refere não estar conseguindo dormir bem, pois fica durante horas pensando em tudo que precisa fazer. Disse que tem lembrança de ter sido assim desde criança. Diagnóstico: transtorno de ansiedade Responda: B. Pensando na fisiopatologia do transtorno de ansiedade generalizada, a patogênese desse transtorno está baseada em alterações em três parâmetros (domínios). Liste esses 3 parâmetros.","itens":[],"gab":"Simpático (autonômico), neuroendócrino e cognitivo (anotação manuscrita de aluno após a correção).","com":"A resposta neuroquímica/hormonal/estrutural foi quase zerada, o que sugere que a professora esperava os domínios autonômico (simpático), neuroendócrino (eixo HHA) e cognitivo.<br><b>Observação:</b> A resposta do aluno (neuroquímico ↑noradrenalina, hormonal ↑cortisol, estrutural ↓BDNF) foi quase zerada. A anotação 'simpática, neuroendócrina, cognitiva' na margem parece ser do aluno, não do professor.","incerta":true},{"id":"UC16-FIS-T9B-Q01","sp":1,"tus":["T9"],"prova":"T9 B (2025/2) Q1","selo":"OF","tipo":"direta","tema":"Eixo HHA na depressão","enun":"A desregulação do eixo hipotálamo-hipófise-adrenal na depressão está associada a:","itens":[],"alts":["Redução de cortisol circulante.","Estimulação exclusiva da via serotoninérgica","Feedback negativo excessivamente potente.","Hiperprodução de TSH e TRH.","Supressão da neurogênese e aumento de estresse oxidativo."],"gab":"E","com":"Na depressão há hipercortisolismo com feedback negativo FALHO (↑CRH, ↑ACTH, ↑cortisol), o que suprime a neurogênese e aumenta o estresse oxidativo."},{"id":"UC16-FIS-T9B-Q02","sp":4,"tus":["T9"],"prova":"T9 B (2025/2) Q2","selo":"OF","tipo":"sentenças","tema":"Esquizofrenia","enun":"Analise as seguintes assertivas sobre a esquizofrenia e assinale abaixo a alternativa correta:","itens":["I. As características psicóticas da esquizofrenia surgem principalmente na infância ou início da adolescência.","II. O início pode ser abrupto ou insidioso, mas a maioria dos indivíduos manifesta um desenvolvimento abrupto.","III. Na esquizofrenia, a estimulação excessiva da via dopaminérgica mesocortical provocaria sintomas positivos como delírios e alucinações.","IV. A prevalência da esquizofrenia em diferentes populações aumenta entre parentes de primeiro grau de um paciente esquizofrênico.","V. Humor depressivo; isolamento; comportamento inadequado; e negligência com a higiene e aparência pessoal estão incluídos entre os sintomas prodrômicos da esquizofrenia."],"alts":["I, II e III","I, II e IV","II, III e V","III, IV e V","IV e V"],"gab":"E","com":"A psicose surge no fim da adolescência ou início da vida adulta, o início costuma ser INSIDIOSO, e os sintomas positivos vêm da via MESOLÍMBICA."},{"id":"UC16-FIS-T9B-Q03","sp":3,"tus":["T9"],"prova":"T9 B (2025/2) Q3","selo":"OF","tipo":"sentenças","tema":"TAG","enun":"Considerando o transtorno de ansiedade generalizada (TAG), analise as seguintes assertivas:","itens":["I. A hiperatividade da via dopaminérgica mesolímbica é considerada a principal explicação fisiopatológica para o transtorno de ansiedade generalizada.","II. No transtorno de ansiedade, a amígdala é considerada o ponto inicial das respostas corporais inerentes ao transtorno.","III. O efeito ansiolítico do GABA parece consistir em reduzir o funcionamento de grupos neuronais no córtex pré-frontal e no hipocampo.","IV. O transtorno de ansiedade generalizada é caracterizado por episódios recorrentes e inesperados de pânico, que constituem o núcleo diagnóstico do transtorno.","V. O diagnóstico de transtorno de ansiedade generalizada exige a presença de sintomas físicos exclusivamente cardiovasculares, como palpitações e dor torácica."],"alts":["I e II","II e III","II, III e IV","I, II, III e IV","I, III e V"],"gab":"B","com":"Nesta prova o item III (GABA no córtex pré-frontal e no hipocampo) foi considerado verdadeiro. I, IV e V são falsos: dopamina é da esquizofrenia, ataques inesperados são do pânico, e os sintomas não são exclusivamente cardiovasculares."},{"id":"UC16-FIS-T9B-Q04","sp":2,"tus":["T9"],"prova":"T9 B (2025/2) Q4","selo":"OF","tipo":"sentenças","tema":"Transtorno bipolar","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar e assinale abaixo a alternativa correta:","itens":["I. A duração mínima de um episódio maníaco é de 1 semana ou qualquer duração que se a gravidade dos sintomas exija hospitalização imediata.","II. Os episódios maníacos e depressivos se alternam regularmente, podendo haver a sequência de um episódio maníaco, depois um depressivo e assim por diante.","III. Na hipomania, os sintomas são menos graves que na mania e não exigem hospitalização ou apresentam sintomas psicóticos.","IV. O transtorno bipolar tipo I caracteriza-se pela presença de pelo menos um episódio maníaco, podendo ou não haver episódios depressivos.","V. A prevalência do transtorno bipolar é maior em homens do que em mulheres, em todas as formas clínicas."],"alts":["I, II e IV","II, III e V","I, III e IV","I, IV e V","III, IV e V"],"gab":"C","com":"Os episódios não se alternam regularmente, e o TB I tem prevalência semelhante entre os sexos (o TB II é mais comum em mulheres)."},{"id":"UC16-FIS-T9B-Q05","sp":1,"tus":["T9"],"prova":"T9 B (2025/2) Q5","selo":"OF","tipo":"sentenças","tema":"Transtorno depressivo maior","enun":"Sobre o Transtorno Depressivo Maior (TDM), avalie as afirmações:","itens":["I. Os episódios devem durar no mínimo 2 semanas, embora possam ser mais longos.","II. Entre os sintomas diagnósticos estão fadiga, insônia ou hipersonia, ideação suicida e sentimentos de inutilidade.","III. Para o diagnóstico, basta a presença de um único sintoma em qualquer duração.","IV. Em quadros de depressão, O NF-k um fator de transcrição envolvido no controle da expressão de diversos genes, provocaria a diminuição de monoaminas como a serotonina.","V. No transtorno depressivo maior, o número de sintomas muitas vezes oscila acima e abaixo do limiar para o transtorno depressivo persistente."],"alts":["I, II e IV","II, IV e V","I, II e V","I, III e V","III, IV e V"],"gab":"A","com":"São exigidos ≥5 sintomas por ≥2 semanas. Oscilar acima e abaixo do limiar é característica do TDP em relação ao episódio depressivo maior, não o inverso."},{"id":"UC16-FIS-T9B-Q06","sp":4,"tus":["T9"],"prova":"T9 B (2025/2) Q6","selo":"OF","tipo":"caso","tema":"Delírio","enun":"Paciente de 34 anos procura atendimento após familiares relatarem comportamento estranho. Durante a consulta, o paciente afirma: \"Eu tenho certeza absoluta de que meu vizinho instalou câmeras secretas dentro da minha casa e que a televisão transmite mensagens só para mim.\" A alteração do pensamento detectada neste caso é:","itens":[],"alts":["Incongruência afetiva","Alucinação auditiva","Delírio","Alucinação visual","Discurso desorganizado"],"gab":"C","com":"Crença falsa e inabalável (delírio persecutório e de referência), alteração do conteúdo do pensamento. Não há percepção sem objeto."},{"id":"UC16-FIS-T9B-Q07","sp":2,"tus":["T9"],"prova":"T9 B (2025/2) Q7","selo":"OF","tipo":"direta","tema":"Neuroquímica do transtorno bipolar","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar e assinale a incorreta:","itens":[],"alts":["O lítio modula a neurotransmissão glutamatérgica, aumentando agudamente a atividade do receptor NMDA, mas reduzindo-a após uso crônico.","Alterações neuroquímicas no transtorno bipolar incluem aumento de noradrenalina em mania, disfunção dopaminérgica e diminuição de GABA.","O sistema serotoninérgico está implicado, com evidências de diminuição de cálcio intracelular induzida por serotonina durante a mania.","Estudos com gêmeos sugerem que a herdabilidade do transtorno bipolar poderia situar-se entre 70 e 80%.","No transtorno bipolar, o aumento dos níveis de dopamina é associado aos episódio de mania."],"gab":"C","com":"Na mania há AUMENTO do cálcio intracelular induzido por serotonina (hiperexcitabilidade); falar em diminuição é o erro."},{"id":"UC16-FIS-T9B-Q08","sp":2,"tus":["T9"],"prova":"T9 B (2025/2) Q8","selo":"OF","tipo":"caso","tema":"Episódio maníaco","enun":"Paciente masculino, 28 anos, professor universitário, comparece à consulta acompanhado da irmã, que relata comportamento \"diferente\" nas últimas semanas. Segundo ela, o paciente está muito falante com pensamentos acelerados, dormindo apenas 3 horas por noite sem apresentar cansaço, gastando grande parte de suas economias em investimentos de alto risco e exibindo comportamento sexual desinibido. Ele minimiza as preocupações da família e afirma que nunca esteve \"tão bem e produtivo\". Com base no caso descrito e nos critérios do DSM-5 para transtorno bipolar, analise as afirmativas:","itens":["I. O quadro clínico é compatível com episódio maníaco, pois há humor persistentemente elevado/expansivo, duração superior a 7 dias e prejuízo funcional importante.","II. A presença de redução da necessidade de sono, fuga de ideias e comportamento impulsivo reforça o diagnóstico de mania.","III. O diagnóstico diferencial deve incluir transtorno de personalidade borderline, esquizofrenia, intoxicação por substâncias e hipertireoidismo.","IV. Episódio hipomaníaco também poderia ser considerado, já que o paciente mantém funcionalidade preservada e não apresenta risco social.","V. A ausência de relato de tristeza ou anedonia exclui a hipótese de transtorno afetivo bipolar."],"alts":["I e V","I, II e III","II, III e IV","I, II, III e IV","III e V"],"gab":"B","com":"Gastar as economias em investimentos de risco é prejuízo grave, o que afasta a hipomania (IV). Um único episódio maníaco já basta para TB I, sem precisar de depressão (V)."},{"id":"UC16-FIS-T9B-Q09","sp":3,"tus":["T9"],"prova":"T9 B (2025/2) Q9","selo":"OF","tipo":"caso","tema":"Transtorno do pânico: sintomas","enun":"Paciente masculino de 36 anos foi diagnosticado com transtorno do pânico. Para o diagnóstico, é necessária a presença de pelo menos quatro sintomas típicos de ataque de pânico, que podem incluir:","itens":[],"alts":["Tremores, sudorese, cefaleia constante, amnésia","Sudorese, náusea, sensação de asfixia, taquicardia","Polifagia, palpitações, polidipsia","Taquicardia, ondas de calor, torpor e amnésia","Hiperatividade, tontura, dormência e desconforto torácico"],"gab":"B","com":"Sudorese, náusea, asfixia e taquicardia estão no DSM-5; cefaleia constante, amnésia, torpor, polifagia/polidipsia e hiperatividade não estão."},{"id":"UC16-FIS-T9B-Q10","sp":3,"tus":["T9"],"prova":"T9 B (2025/2) Q10","selo":"OF","tipo":"direta","tema":"TAG: critérios","enun":"Paciente feminino, 40 anos, relata preocupação excessiva e ansiedade persistente há anos, acompanhadas de insônia e tensão muscular, sendo diagnosticada com transtorno de ansiedade generalizada (TAG). As seguintes afirmativas sobre esse transtorno estão corretas, exceto:","itens":[],"alts":["O transtorno pode ter início ainda na infância e tende a persistir na vida adulta se não tratado.","Para o diagnóstico de TAG, a ansiedade e a preocupação devem estar associadas a pelo menos dois sintomas, com duração mínima de 3 meses.","O TAG pode ser confundido com sintomas decorrentes dos efeitos fisiológicos de uma substância ou de outra condição médica, devendo estes ser excluídos no diagnóstico.","O curso clínico tende a ser crônico, com remissões e recidivas, podendo oscilar entre formas sindrômicas e subsindrômicas.","O diagnóstico diferencial deve incluir condições médicas gerais e transtornos induzidos por substâncias, como uso de estimulantes."],"gab":"B","com":"O TAG exige ≥3 sintomas (1 em crianças) por ≥6 meses. A alternativa erra os dois números."},{"id":"UC16-FIS-T9B-Q11","sp":3,"tus":["T9"],"prova":"T9 B (2025/2) Q11","selo":"OF","tipo":"direta","tema":"Transtorno de pânico","enun":"A alternativa que melhor descreve o Transtorno de Pânico é:","itens":[],"alts":["Crises de ansiedade sempre desencadeadas por estímulos externos específicos, sem ocorrência de episódios inesperados nem preocupação com recorrência.","Ansiedade antecipatória ocasional, acompanhada por evitação sistemática de locais movimentados, caracterizando essencialmente uma fobia específica.","Ataques episódicos de ativação autonômica, como palpitações, tremores e sudorese, que surgem apenas após situações de estresse claramente identificáveis.","Episódios inesperados e recorrentes de ansiedade intensa, seguidos por preocupação persistente com novos ataques e modificações comportamentais para preveni-los.","Ataques de pânico isolados e autolimitados, sem repercussão significativa no funcionamento social ou ocupacional."],"gab":"D","com":"Transtorno de pânico = ataques INESPERADOS e recorrentes + ≥1 mês de preocupação ou mudança de comportamento. Ataques só com gatilho específico sugerem fobia."},{"id":"UC16-FIS-T9B-Q12","sp":4,"tus":["T9"],"prova":"T9 B (2025/2) Q12","selo":"OF","tipo":"direta","tema":"Esquizofrenia","enun":"Assinale a afimativa incorreta sobre a esquizofrenia:","itens":[],"alts":["Os sintomas psicóticos tendem a diminuir ao longo da vida, talvez pelo declínio normal na atividade dopaminérgica relacionada ao envelhecimento.","A hiperativação da via mesolímbica dopaminérgica induz sintomas positivos de esquizofrenia através do aumento da estimulação de receptores D2 nas áreas límbicas.","Acredita-se que pacientes com esquizofrenia têm menos responsividade em receptores NMDA do glutamato, o que diminuiria a transmissão glutamatérgica.","Complicações obstétricas e perinatais, o como retardo no crescimento uterino, trariam um risco de 3x maior de desenvolver esquizofrenia, segundo alguns estudos.","A catatonia é caracterizada exclusivamente por imobilidade e ausência de movimentos voluntários, não englobando manifestações de agitação ou estereotipias motoras"],"gab":"E","com":"A catatonia inclui tanto estupor/imobilidade quanto agitação, estereotipias, negativismo e posturas; o 'exclusivamente' torna a alternativa falsa."},{"id":"UC16-FIS-T9B-Q13a","sp":4,"tus":["T9"],"prova":"T9 B (2025/2) Q13a","selo":"OF","tipo":"discursiva","tema":"Esquizofrenia: diagnóstico","enun":"Elabore uma hipótese diagnóstica para cada um dos seguintes casos: A.Um paciente de 23 anos apresenta retraimento social, queda no desempenho acadêmico e embotamento afetivo há 2 meses. Evolui, então, com delírios persecutórios e alucinações auditivas durante 1 mês e meio, seguidos de melhora parcial, permanecendo apatia e pobreza de discurso por mais 3 meses. Considerando os critérios do DSM-5, o diagnóstico mais provável:","itens":[],"gab":"Esquizofrenia. (resposta de duas alunas, ambas com nota cheia)","com":"Prodrômica (2 meses) + fase ativa (1,5 mês) + residual (3 meses) somam mais de 6 meses, com ≥1 mês de fase ativa: esquizofrenia, não transtorno esquizofreniforme."},{"id":"UC16-FIS-T9B-Q13b","sp":2,"tus":["T9"],"prova":"T9 B (2025/2) Q13b","selo":"OF","tipo":"discursiva","tema":"Ciclotimia","enun":"Elabore uma hipótese diagnóstica para cada um dos seguintes casos: B. Paciente masculino, 25 anos, relata há cerca de 3 anos oscilações frequentes de humor: períodos de maior energia, loquacidade e irritabilidade que duram alguns dias, alternados com fases de desânimo, fadiga e perda de interesse, também de curta duração. Nunca preencheu critérios completos para episódio maníaco ou depressivo maior. Mantém funcionamento social e laboral, embora com instabilidade.","itens":[],"gab":"Transtorno ciclotímico. (resposta de duas alunas, ambas com nota cheia)","com":"Há ≥2 anos de oscilações hipomaníacas e depressivas subliminares, sem nunca fechar critérios de episódio."},{"id":"UC16-FIS-T9B-Q13c","sp":1,"tus":["T9"],"prova":"T9 B (2025/2) Q13c","selo":"OF","tipo":"discursiva","tema":"Transtorno depressivo maior","enun":"Elabore uma hipótese diagnóstica para cada um dos seguintes casos: C. Paciente feminina, 40 anos, refere humor deprimido e anedonia persistentes há 4 semanas, acompanhados de insônia, fadiga intensa, sentimentos de inutilidade e pensamentos recorrentes de morte. Não há história prévia de episódios maníacos ou hipomaníacos. O quadro causa prejuízo significativo no desempenho profissional e familiar.","itens":[],"gab":"Transtorno depressivo maior. (resposta de duas alunas, ambas com nota cheia)","com":"São ≥5 sintomas (incluindo humor deprimido e anedonia) por mais de 2 semanas, com prejuízo e sem história de mania ou hipomania."},{"id":"UC16-FIS-T9B-Q13d","sp":1,"tus":["T9"],"prova":"T9 B (2025/2) Q13d","selo":"OF","tipo":"discursiva","tema":"TDDH","enun":"Elabore uma hipótese diagnóstica para cada um dos seguintes casos: D. Paciente masculino, 10 anos, apresenta explosões de raiva graves e recorrentes, desproporcionais ao estímulo, ocorrendo várias vezes por semana em casa e na escola. Entre os episódios, permanece irritável quase todos os dias. Os sintomas persistem há mais de 12 meses, sem períodos prolongados de estabilidade. Não há história de mania ou hipomania.","itens":[],"gab":"Transtorno disruptivo da desregulação do humor (TDDH). (resposta de duas alunas, ambas com nota cheia)","com":"Explosões de raiva graves (≥3x/semana) em 2 ambientes, irritabilidade entre elas, há ≥12 meses, numa criança entre 6 e 18 anos."},{"id":"UC16-FIS-T10-Q01","sp":3,"tus":["T10"],"prova":"T10 (2026/1) Q1","selo":"OF","tipo":"caso","tema":"TAG: neurobiologia","enun":"Uma mulher de 34 anos procura atendimento relatando preocupação persistente com diferentes aspectos da vida cotidiana há cerca de um ano. Refere tensão muscular constante, fadiga, dificuldade de concentração e sono não reparador. Durante a avaliação, relata sensação de alerta contínuo mesmo em situações rotineiras. Do ponto de vista neurobiológico, a persistência desse estado de vigilância está mais associada a qual mecanismo?","itens":[],"alts":["Hiperatividade da amígdala associada à redução da capacidade do córtex pré-frontal de modular respostas ao medo.","Aumento da inibição cortical sobre a amígdala, aumento sustentado da resposta autonômica ao estresse.","Redução da responsividade da amígdala a estímulos ambíguos, favorecendo menor vigilância ambiental.","Ativação persistente do eixo HHA, com aumento de cortisol, porém preservação da retroalimentação negativa hipocampal ao longo do tempo"],"gab":"A","com":"No TAG a amígdala hiper-reativa escapa do controle 'de cima para baixo' do córtex pré-frontal. D erra ao dizer que o feedback hipocampal fica preservado."},{"id":"UC16-FIS-T10-Q03","sp":2,"tus":["T10"],"prova":"T10 (2026/1) Q3","selo":"VE","tipo":"caso","tema":"Hipomania","enun":"Um homem de 28 anos apresenta fala acelerada, redução da necessidade de sono e alguns gastos impulsivos, embora dentro do limite do seu salário. O paciente já teve diagnóstico de depressão e acha que o comportamento atual deve estar associado à melhoria do seu quadro pela medição prescrita. Esse quadro clínico é mais compatível com:","itens":[],"alts":["Episódio depressivo maior","Episódio hipomaníaco","Episódio maníaco","Transtorno ciclotímico"],"gab":"B","com":"Sintomas de elevação do humor SEM prejuízo grave (gastos 'dentro do limite do salário'), sem psicose e sem internação = hipomania."},{"id":"UC16-FIS-T10-Q04","sp":4,"tus":["T10"],"prova":"T10 (2026/1) Q4","selo":"OF","tipo":"direta","tema":"Esquizofrenia: neurobiologia","enun":"Sobre a esquizofrenia é correto afirmar que:","itens":[],"alts":["Na esquizofrenia, a redução da atividade GABAérgica cortical pode contribuir para aumento da atividade dopaminérgica mesolímbica.","A hiperativação da via dopaminérgica mesocortical induz sintomas positivos de esquizofrenia através do aumento da estimulação de receptores D2.","Pacientes com esquizofrenia têm maior responsividade em receptores NMDA do glutamato, o que diminuiria a transmissão glutamatérgica.","Complicações obstétricas e infecções perinatais parecem não trazer aumento real do risco para esquizofrenia."],"gab":"A","com":"A perda do freio GABAérgico cortical desinibe a dopamina mesolímbica. Os positivos vêm da via mesoLÍMBICA, a responsividade NMDA é MENOR, e as complicações perinatais aumentam o risco."},{"id":"UC16-FIS-T10-Q05","sp":1,"tus":["T10"],"prova":"T10 (2026/1) Q5","selo":"VE","tipo":"sentenças","tema":"Fisiopatologia da depressão","enun":"Considerando os mecanismos fisiopatológicos atualmente implicados na depressão, analise as assertivas:","itens":["I. Redução da expressão de BDNF, com prejuízo da plasticidade sináptica em circuitos límbicos.","II. Ativação do eixo hipotálamo-hipófise-adrenal por citocinas [ilegível]","III. Liberação de monoaminas no sistema nervoso central como resultado de processos inflamatórios.","IV. Ativação de vias inflamatórias que favorecem excitotoxicidade neuronal e prejuízo da plasticidade sináptica.","V. Redução da atividade glutamatérgica cortical, com diminuição da excitabilidade neuronal."],"alts":["I, II e IV","II, III e IV","I, II e III","I, IV e V","III, IV e V"],"gab":"A","com":"A inflamação REDUZ a disponibilidade de monoaminas (desvia o triptofano para a via da quinurenina), e a depressão envolve excitotoxicidade glutamatérgica, não redução de glutamato."},{"id":"UC16-FIS-T10-Q06","sp":2,"tus":["T10"],"prova":"T10 (2026/1) Q6","selo":"OF","tipo":"direta","tema":"Neuroquímica da mania","enun":"Durante episódios maníacos do transtorno bipolar, diversas alterações neuroquímicas podem ser observadas. Qual das seguintes alterações neurobiológicas está mais associada ao desenvolvimento dos sintomas de mania?","itens":[],"alts":["Redução da transmissão dopaminérgica no sistema mesolímbico","Hipoatividade glutamatérgica cortical","Aumento da atividade dopaminérgica associado à hiperexcitabilidade neuronal","Aumento da atividade GABAérgica no córtex pré-frontal"],"gab":"C","com":"Na mania há excesso de dopamina com hiperexcitabilidade neuronal (mais glutamato, menos GABA). As demais invertem o sentido."},{"id":"UC16-FIS-T10-Q07","sp":2,"tus":["T10"],"prova":"T10 (2026/1) Q7","selo":"OF","tipo":"sentenças","tema":"Bipolar tipo I","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar tipo I e assinale abaixo a alternativa correta:","itens":["I. O diagnóstico do transtorno bipolar tipo I requer um ou mais episódios maníacos, de no mínimo 4 dias, durante o curso da vida.","II. Os episódios maníacos e depressivos não se alternam regularmente, podendo haver sequência de episódios maníacos, depois um depressivo e assim por diante.","III. O transtorno bipolar do tipo I é marcado por episódios de mania, não havendo exigência de psicose ou de experiência de um episódio depressivo maior na vida para o seu diagnóstico.","IV. A média de idade para o primeiro episódio maníaco ou depressivo maior é de aproximadamente 18 anos, e não relatos de início na senescência.","V. Episódios maníacos com sintomas psicóticos ou que necessitem hospitalização caracterizam transtorno bipolar tipo I, desde que excluídas outras causas clínicas ou induzidas por substâncias."],"alts":["I, II e III","II, III e V","II, IV e V","I, III e V","II e V"],"gab":"B","com":"A mania exige 7 dias (4 dias é hipomania), e há casos de início na senescência."},{"id":"UC16-FIS-T10-Q08","sp":4,"tus":["T10"],"prova":"T10 (2026/1) Q8","selo":"OF","tipo":"sentenças","tema":"Esquizofrenia","enun":"Analise as afirmativas sobre esquizofrenia e assinale abaixo a alternativa correta:","itens":["I. A catatonia é caracterizada por alterações motoras que podem incluir imobilidade, posturas anormais, negativismo ou agitação motora sem propósito aparente.","II. Sintomas positivos da esquizofrenia incluem manifestações como delírios, alucinações e desorganização do pensamento.","III. Os sintomas psicóticos da esquizofrenia podem diminuir em intensidade ao longo da vida, possivelmente em associação com a redução da atividade dopaminérgica relacionada ao envelhecimento.","IV. As alucinações são crenças fixas, não passíveis de mudança à luz de evidências contrárias.","V. Para o diagnóstico da esquizofrenia, basta a presença de delírios ou alucinações durante pelo menos um mês, independentemente da presença de outros sintomas."],"alts":["I, II e III","I, III e IV","II, III e V","I, II e V","II e IV"],"gab":"A","com":"IV define DELÍRIO, não alucinação. V é falsa porque o DSM-5 exige ≥2 sintomas por 1 mês e sinais contínuos por 6 meses."},{"id":"UC16-FIS-T10-Q09","sp":1,"tus":["T10"],"prova":"T10 (2026/1) Q9","selo":"OF","tipo":"direta","tema":"Hipótese monoaminérgica","enun":"A hipótese monoaminérgica da depressão foi proposta a partir da observação de que certos fármacos que aumentam a disponibilidade de monoaminas podem melhorar os sintomas depressivos. Uma das principais limitações dessa hipótese é:","itens":[],"alts":["A incapacidade de explicar a relação entre fatores psicossociais e o surgimento da depressão.","O fato de que o aumento sináptico de monoaminas ocorre rapidamente, enquanto a melhora clínica costuma levar semanas.","A inexistência de evidências de participação da serotonina na regulação do humor.","A ausência de eficácia terapêutica dos antidepressivos que modulam monoaminas."],"gab":"B","com":"A latência de 2 a 4 semanas da resposta clínica, contra o aumento imediato de monoaminas, levou às hipóteses neurotrófica e de neuroplasticidade."},{"id":"UC16-FIS-T10-Q10","sp":1,"tus":["T10"],"prova":"T10 (2026/1) Q10","selo":"OF","tipo":"caso","tema":"TDDH","enun":"Um menino de 9 anos é levado ao ambulatório de psiquiatria infantil pelos pais devido a episódios frequentes de irritabilidade intensa. Segundo os responsáveis, há cerca de dois anos a criança apresenta explosões de raiva desproporcionais à situação, ocorrendo várias vezes por semana, muitas vezes em resposta a pequenas frustrações. Durante esses episódios, o paciente pode gritar, quebrar objetos ou agredir verbalmente familiares. O desenvolvimento neuropsicomotor foi adequado e não há história de uso de substâncias ou doenças clínicas relevantes. Com base nesse quadro clínico, qual é o diagnóstico mais compatível?","itens":[],"alts":["Transtorno bipolar tipo I","Transtorno explosivo intermitente","Transtorno disruptivo da desregulação do humor","Esquizofrenia"],"gab":"C","com":"Criança com explosões de raiva frequentes e desproporcionais, com início antes dos 10 anos, = TDDH. No transtorno explosivo intermitente não há irritabilidade persistente entre as crises."},{"id":"UC16-FIS-T10-Q11","sp":4,"tus":["T10"],"prova":"T10 (2026/1) Q11","selo":"OF","tipo":"caso","tema":"Domínios sintomatológicos da esquizofrenia","enun":"Um homem de 22 anos é levado à consulta por familiares devido a mudanças progressivas de comportamento nos últimos dois anos. O paciente abandonou a universidade, passou a apresentar isolamento social e demonstra pouca iniciativa para atividades cotidianas. Nos últimos meses, relata ouvir vozes que comentam suas ações e afirma acreditar que vizinhos instalaram dispositivos para monitorá-lo. Durante a entrevista, apresenta discurso pouco organizado e dificuldade em manter a atenção em perguntas mais complexas. Considerando os diferentes domínios sintomatológicos da esquizofrenia, qual das alternativas identifica corretamente exemplos de sintomas positivos, negativos e cognitivos, respectivamente, presentes no caso?","itens":[],"alts":["Alucinações auditivas; isolamento social; dificuldade de atenção.","Delírios persecutórios; discurso desorganizado; retraimento social.","Discurso desorganizado; alucinações auditivas; prejuízo de iniciativa.","Isolamento social; delírios persecutórios; dificuldade de atenção."],"gab":"A","com":"A ordem pedida é positivo, negativo, cognitivo: alucinação, isolamento social, déficit de atenção. Discurso desorganizado é positivo/desorganização, não negativo."},{"id":"UC16-FIS-T10-Q12","sp":3,"tus":["T10"],"prova":"T10 (2026/1) Q12","selo":"OF","tipo":"discursiva","tema":"Dor torácica na crise de ansiedade","enun":"Paciente, masculino, 41 anos procura atendimento no pronto-socorro por dor torácica súbita associada a sensação de sufocamento, tremores e medo intenso de morrer. Refere que os sintomas começaram em repouso. Ao exame, apresenta taquipneia e parestesias em mãos. ECG e troponina iniciais são normais. Liste e explique 3 mecanimos fisiopatológicos que levam ao paciente com crise de ansiedade a experimentar dor torácica.","itens":[],"gab":"Espasmo coronário funcional (↑noradrenalina → vasoconstrição); hiperventilação (hipocapnia/alcalose, desvio da curva de dissociação da hemoglobina para a esquerda, menor oferta de O2); tensão muscular (o professor anotou 'intercostal?' ao lado de 'intervertebral'). Resposta do aluno com nota parcial. Anotação a lápis de aluno acrescenta 'hipersensibilização interoceptiva'.","com":"Mecanismos clássicos: vasoespasmo coronário por catecolaminas, hiperventilação (hipocapnia, que causa vasoconstrição e parestesias) e tensão da musculatura intercostal/torácica; a hipersensibilidade interoceptiva amplifica a dor.<br><b>Observação:</b> Nota parcial, sem indicação de quais itens foram aceitos.","incerta":true},{"id":"UC16-FIS-T10-Q13a","sp":4,"tus":["T10"],"prova":"T10 (2026/1) Q13a","selo":"IN","tipo":"discursiva","tema":"Poda sináptica","enun":"A esquizofrenia é atualmente compreendida como um transtorno associado a alterações no desenvolvimento e funcionamento de circuitos cerebrais. A. Explique brevemente o que é a poda sináptica, relacionando-o ao aparecimento dos sintomas geralmente no final da adolescência ou início da vida adulta. (0,5 ponto)","itens":[],"gab":"Poda sináptica é a eliminação fisiológica das sinapses pouco usadas ou redundantes durante o neurodesenvolvimento, feita pela micróglia com marcação pelo sistema complemento (C4/C3), para refinar os circuitos e torná-los mais eficientes; seu pico ocorre na adolescência, sobretudo no córtex pré-frontal. Na esquizofrenia a poda seria excessiva (variantes que aumentam a expressão de C4), com perda de espinhas dendríticas e de substância cinzenta pré-frontal e desconexão dos circuitos córtico-límbicos. Como essa etapa final de maturação acontece no fim da adolescência e início da vida adulta, é nesse momento que a reserva de sinapses se torna insuficiente e os sintomas aparecem.","com":"O professor queria o conceito de neurodesenvolvimento (eliminação de sinapses) e o vínculo temporal com a maturação do pré-frontal. 'Aumento de dopamina na via mesolímbica' é consequência da desregulação dos circuitos, não a definição de poda — por isso a resposta foi riscada."},{"id":"UC16-FIS-T10-Q13b","sp":4,"tus":["T10"],"prova":"T10 (2026/1) Q13b","selo":"OF","tipo":"discursiva","tema":"Alterações cerebrais na esquizofrenia","enun":"A esquizofrenia é atualmente compreendida como um transtorno associado a alterações no desenvolvimento e funcionamento de circuitos cerebrais. B. Cite duas alterações estruturais ou funcionais cerebrais frequentemente descritas em pacientes com esquizofrenia. (0,5 ponto)","itens":[],"gab":"Resposta do aluno com nota parcial: 'aumento da área cinzenta, hiperatividade da amígdala'; o professor circulou trechos sem indicar qual foi aceito.","com":"Achados clássicos: aumento dos ventrículos laterais, redução da substância cinzenta (córtex pré-frontal e temporal, hipocampo) e hipofrontalidade. 'Aumento da área cinzenta' está invertido.<br><b>Observação:</b> Nota parcial; não dá para saber qual das duas alterações foi aceita.","incerta":true},{"id":"UC16-FIS-T11-Q01","sp":2,"tus":["T11"],"prova":"T11 (2026/2) Q1","selo":"OF","tipo":"direta","tema":"Bipolar tipo II","enun":"Denomina-se transtorno bipolar tipo II, o transtorno em que acontece:","itens":[],"alts":["pelo menos um episódio de mania, que pode ter sido antecedido ou seguido por episódios depressivos maiores ou hipomaníacos.","um ou mais episódios depressivos maiores associados a pelo menos um episódio de mania.","um ou mais episódios depressivos maiores e pelo menos um episódio hipomaníaco, sem história de episódio maníaco.","um episódio hipomaníaco acompanhado por ideação suicida.","somente episódios hipomaníacos."],"gab":"C","com":"TB II: depressão maior + hipomania, sem nunca ter tido mania. Qualquer episódio maníaco faz do quadro um tipo I.","rep":2},{"id":"UC16-FIS-T11-Q02","sp":4,"tus":["T11"],"prova":"T11 (2026/2) Q2","selo":"OF","tipo":"caso","tema":"Sintomas negativos","enun":"Durante a anamnese de um paciente com esquizofrenia crônica, o médico observa que ele responde a perguntas com pouquíssimas palavras, sem conteúdo informativo, e mantém a expressão facial neutra mesmo ao falar de temas tristes. Estes sintomas são classificados como:","itens":[],"alts":["Alogia e Embotamento Afetivo","Delírio Niilista e Avolição","Catatonia e Anedonia","Tangencialidade e Descarrilamento","Sintomas Cognitivos de Memória"],"gab":"A","com":"Pobreza de discurso é alogia, e expressão facial neutra é embotamento afetivo, ambos sintomas negativos. Tangencialidade e descarrilamento são desorganização."},{"id":"UC16-FIS-T11-Q03","sp":1,"tus":["T11"],"prova":"T11 (2026/2) Q3","selo":"OF","tipo":"direta","tema":"Sintomas da depressão","enun":"Assinale a alternativa que apresenta um sintoma característico da depressão maior:","itens":[],"alts":["Fuga de ideias e aumento da atividade dirigida a objetivos.","Anedonia e redução persistente do interesse por atividades habitualmente prazerosas.","Delírios persecutórios como manifestação obrigatória da doença.","Redução da necessidade de sono sem sensação de cansaço.","Crises súbitas e recorrentes de medo intenso, com pico em poucos minutos."],"gab":"B","com":"Anedonia é um dos dois sintomas nucleares do TDM. A e D são mania, E é pânico, e psicose não é obrigatória."},{"id":"UC16-FIS-T11-Q04","sp":3,"tus":["T11"],"prova":"T11 (2026/2) Q4","selo":"OF","tipo":"direta","tema":"Neurobiologia da ansiedade e do pânico","enun":"Assinale a assertiva incorreta sobre a neurobiologia do Transtorno de Ansiedade Generalizada (TAG) e do Transtorno de Pânico:","itens":[],"alts":["A amígdala participa da detecção e processamento de estímulos ameaçadores e apresenta alterações de reatividade em diferentes transtornos de ansiedade.","O cortisol elevado no estresse crônico atua no hipocampo estimulando receptores de glicocorticoides que, por retroalimentação positiva, aumentam a liberação de CRH para proteger os neurônios da exaustão metabólica.","Na resposta de medo, a amígdala comunica-se com o núcleo parabraquial na ponte, que por sua vez estimula o bulbo a sinalizar aos pulmões a necessidade de ar extra, resultando em hiperventilação e dispneia.","A serotonina exerce um papel ambivalente na regulação da ansiedade, agindo como ansiogênica na amígdala e como ansiolítica na matéria cinzenta periaquedutal dorsal.","O efeito ansiolítico dos benzodiazepínicos decorre da potencialização do receptor GABA-A, o que promove o aumento do influxo de íons Cloro (Cl-) nos neurônios do sistema límbico, resultando em hiperpolarização e redução do disparo neuronal."],"gab":"B","com":"O cortisol crônico LESA o hipocampo, que perde o feedback NEGATIVO sobre o eixo HHA; não há 'retroalimentação positiva para proteger os neurônios'."},{"id":"UC16-FIS-T11-Q05","sp":4,"tus":["T11"],"prova":"T11 (2026/2) Q5","selo":"OF","tipo":"sentenças","tema":"Esquizofrenia: fisiopatologia e critérios","enun":"Considere as seguintes assertivas sobre a fisiopatologia e os critérios diagnósticos da esquizofrenia:","itens":["I. Em geral, os pacientes mantêm a clareza de consciência preservada, mas apresentam déficits cognitivos em domínios cognitivos, como atenção, que são considerados os principais responsáveis pela incapacidade funcional a longo prazo.","II. Alucinações auditivas são as modalidades sensoriais mais frequentes na esquizofrenia; por outro lado, a predominância de alucinações visuais ou o início súbito de psicose em idosos deve levar à investigação imediata de Delirium ou causas orgânicas.","III. A hipótese do neurodesenvolvimento propõe que a poda sináptica durante a adolescência ocorre de forma deficitária, resultando em um aumento anômalo da conectividade neuronal no córtex pré-frontal.","IV. Os sintomas psicóticos positivos tendem a se intensificar significativamente após a quinta década de vida devido ao aumento fisiológico da atividade dopaminérgica relacionado ao envelhecimento.","V. Para o diagnóstico de esquizofrenia segundo o DSM-5, é exigida a presença de sinais contínuos da perturbação por no mínimo seis meses, período que deve incluir pelo menos um mês de sintomas da fase ativa."],"alts":["I e II.","II, III e IV","I, IV e V","I, II e III","I, II e V"],"gab":"E","com":"A poda é EXCESSIVA, com redução da conectividade pré-frontal, e a dopamina DIMINUI com a idade, atenuando os sintomas positivos."},{"id":"UC16-FIS-T11-Q06","sp":2,"tus":["T11"],"prova":"T11 (2026/2) Q6","selo":"OF","tipo":"direta","tema":"Hipomania","enun":"Assinale a alternativa que melhor define a hipomania:","itens":[],"alts":["Um período distinto de humor anormal e persistentemente elevado, expansivo ou irritável, com aumento anormal da atividade ou energia, com duração mínima de quatro dias consecutivos","Autoestima inflada ou grandiosidade, redução da necessidade de sono, mais loquaz que o habitual ou pressão para continuar falando, por um período mínimo de uma semana.","A perturbação do humor é suficientemente grave a ponto de causar prejuízo acentuado no funcionamento social ou profissional.","Perda da capacidade de cuidar de si, estando sujeito ao cuidado familiar.","Período compreendido entre uma fase maníaca e uma fase depressiva."],"gab":"A","com":"Hipomania = ≥4 dias consecutivos. Uma semana e prejuízo acentuado definem mania."},{"id":"UC16-FIS-T11-Q07","sp":3,"tus":["T11"],"prova":"T11 (2026/2) Q7","selo":"OF","tipo":"sentenças","tema":"Dor torácica: diagnóstico diferencial","enun":"Paciente, 25 anos, sexo feminino, chega à emergência com dor no peito, falta de ar e formigamento nas mãos. ECG e troponina inicial estão normais. Considere as seguintes assertivas sobre o manejo e diagnóstico diferencial:","itens":["I. Diante de dor torácica e dispneia agudas, causas orgânicas potencialmente graves devem ser consideradas antes de atribuir os sintomas exclusivamente a uma crise de ansiedade.","II. A normalidade do ECG e da troponina inicial em um paciente jovem permite confirmar imediatamente o diagnóstico de Transtorno de Pânico, dispensando a investigação de outras causas orgânicas como hipertireoidismo ou arritmias.","III. Se a paciente apresentar dor à palpação muscular intercostal que é reproduzível ao exame físico, a hipótese de dor musculoesquelética por tensão muscular sustentada ganha força diagnóstica.","IV. Deve-se obrigatoriamente realizar um cateterismo cardíaco imediato, pois o espasmo coronário funcional induzido por catecolaminas em crises de ansiedade causa lesões obstrutivas permanentes.","V. O Escore de Wells deve ser utilizado para avaliar a probabilidade de Embolia Pulmonar (TEP), visto que esta condição pode se manifestar com dispneia súbita e pânico, mimetizando uma crise de ansiedade."],"alts":["I, II e V","II, III e IV","I e III","I, III e V","I, II, III e V"],"gab":"D","com":"Pânico é diagnóstico de exclusão (II falsa), e o espasmo funcional não causa lesões obstrutivas nem exige cateterismo (IV falsa)."},{"id":"UC16-FIS-T11-Q08","sp":1,"tus":["T11"],"prova":"T11 (2026/2) Q8","selo":"OF","tipo":"direta","tema":"TDDH","enun":"Assinale a assertiva correta sobre o Transtorno Disruptivo da Desregulação do Humor (TDDH):","itens":[],"alts":["O diagnóstico de TDDH pode ser aplicado pela primeira vez em crianças a partir dos 4 anos de idade, desde que as explosões de raiva sejam observáveis em pelo menos um ambiente, como a casa ou a escola.","Para o diagnóstico, as explosões de raiva (verbais ou comportamentais) devem ocorrer, em média, três ou mais vezes por semana, e o humor entre as explosões deve ser persistentemente irritável ou zangado na maior parte do dia.","A principal característica que diferencia o TDDH do Transtorno Bipolar na infância é a gravidade dos sintomas; enquanto o TDDH apresenta sintomas psicóticos leves, o Transtorno Bipolar é definido apenas por episódios de irritabilidade.","O diagnóstico de TDDH deve ser registrado concomitantemente ao de Transtorno Explosivo Intermitente (TEI) caso a criança apresente explosões de raiva por um período superior a três meses.","No Transtorno de Oposição Desafiante (TOD), o núcleo central é a desregulação persistente e global do humor, o que o torna clinicamente idêntico ao TDDH quanto à fisiopatologia do afeto."],"gab":"B","com":"O diagnóstico só vale entre 6 e 18 anos, com início antes dos 10 anos e sintomas em ≥2 ambientes. TDDH não coexiste com TEI ou TOD (prevalece o TDDH)."},{"id":"UC16-FIS-T11-Q09","sp":4,"tus":["T11"],"prova":"T11 (2026/2) Q9","selo":"OF","tipo":"direta","tema":"Esquizofrenia: neurobiologia","enun":"Assinale a afirmativa correta sobre a esquizofrenia:","itens":[],"alts":["Os sintomas positivos (delírios e alucinações) resultam da hipofunção dopaminérgica na via mesolímbica por falha na ativação do núcleo accumbens.","A hipoatividade da via mesocortical, associada à redução da sinalização dopaminérgica, seria responsável pelos sintomas negativos e déficits cognitivos, que constituem manifestações secundárias aos sintomas psicóticos positivos.","A hipofunção de receptores NMDA em interneurônios gabaérgicos no mesencéfalo reduz o freio inibitório sobre os neurônios dopaminérgicos, culminando em hiperatividade mesolímbica.","Antipsicóticos de segunda geração (atípicos) causam menos efeitos extrapiramidais porque possuem afinidade nula pelos receptores D2 no estriado.","O aumento da prolactina é um efeito adverso exclusivo dos antipsicóticos atípicos, devido ao seu potente antagonismo serotoninérgico 5-HT2A na hipófise."],"gab":"C","com":"Modelo glutamatérgico: hipofunção NMDA nos interneurônios GABA desinibe a dopamina mesolímbica. Os negativos são PRIMÁRIOS, os atípicos têm afinidade D2 (não nula), e a hiperprolactinemia é típica dos típicos (bloqueio D2 túbero-infundibular)."},{"id":"UC16-FIS-T11-Q10","sp":1,"tus":["T11"],"prova":"T11 (2026/2) Q10","selo":"OF","tipo":"sentenças","tema":"Fisiopatologia da depressão","enun":"Analise as seguintes assertivas sobre a fisiopatologia da depressão:","itens":["I. Citocinas pró-inflamatórias como IL-1, IL-2, IL-6 e TNF-α podem estimular a produção de CRH e ACTH.","II. Na depressão, a exposição crônica a altos níveis de cortisol causa neurotoxicidade e atrofia dos neurônios hipocampais.","III. A redução da capacidade do hipocampo em controlar o cortisol cria um ciclo onde o eixo HPA permanece desregulado e hiperativo.","IV. O cortisol elevado estimula diretamente a expressão do gene que produz o BDNF no hipocampo, protegendo-o da morte celular.","V. A retroalimentação negativa é fortalecida em pacientes deprimidos devido à hipersensibilidade dos receptores de glicocorticoides."],"alts":["I, II e III","I e IV","II, III e V","III e IV","I, IV e V"],"gab":"A","com":"O cortisol REDUZ o BDNF, e na depressão a retroalimentação negativa fica ENFRAQUECIDA (resistência dos receptores de glicocorticoide)."},{"id":"UC16-FIS-T11-Q11","sp":3,"tus":["T11"],"prova":"T11 (2026/2) Q11","selo":"OF","tipo":"direta","tema":"Hiperventilação no pânico","enun":"Assinale a alternativa que explica corretamente a ocorrência de parestesias e espasmos musculares em pacientes com hiperventilação, durante uma crise de pânico:","itens":[],"alts":["A hiperventilação causa hipercapnia, que resulta em acidose respiratória, aumentando a fração de cálcio ionizado no plasma","A vasoconstrição cerebral induzida pela hipocapnia ativa diretamente os receptores NMDA periféricos, mimetizando uma descarga de glutamato nos nervos sensitivos.","O aumento do cálcio ionizado no sangue, decorrente da ativação do eixo HPA, estabiliza a membrana neuronal, retardando a repolarização e gerando os tremores.","A hiperventilação provoca hipocapnia e alcalose respiratória; a redução de H+ ligado à albumina aumenta a ligação do cálcio à proteína, reduzindo a fração de cálcio ionizado e aumentando a excitabilidade neuromuscular.","A alcalose metabólica compensatória desloca a curva de dissociação da hemoglobina para a direita, facilitando a liberação de oxigênio e causando hiperatividade muscular."],"gab":"D","com":"Hipocapnia leva a alcalose, com mais cálcio ligado à albumina e menos cálcio ionizado, o que aumenta a excitabilidade (parestesias, tetania). A alcalose desloca a curva para a ESQUERDA."},{"id":"UC16-FIS-T11-Q12a","sp":3,"tus":["T11"],"prova":"T11 (2026/2) Q12a","selo":"IN","tipo":"discursiva","tema":"Hipótese do falso alarme de sufocamento","enun":"Responda: A. Descreva a hipótese do alarme falso de sufocamento na patogênese do Transtorno de Pânico.","itens":[],"gab":"O tronco encefálico teria um 'monitor de sufocamento' que detecta sinais de asfixia iminente (aumento de CO2/queda do pH e lactato) e dispara um alarme inato de sufocação. No transtorno de pânico esse monitor é hipersensível (limiar baixo) e dispara sem que exista falta de ar real — um alarme falso: surgem de forma súbita a sensação de sufocamento/dispneia e a urgência de fugir, seguidas de hiperventilação e da descarga autonômica do ataque. Sustentam a hipótese a indução de ataques por inalação de CO2 ou infusão de lactato nesses pacientes e a hiperventilação crônica, que mantém a pCO2 baixa, longe do limiar do alarme.","com":"O centro da resposta é o erro de detecção: alarme disparado sem asfixia real, por limiar baixo a CO2/lactato, com a dispneia vindo primeiro e a hiperventilação como consequência. A resposta considerada errada tratava a hiperventilação como compensação fisiológica de um excesso real de CO2."},{"id":"UC16-FIS-T11-Q12b","sp":2,"tus":["T11"],"prova":"T11 (2026/2) Q12b","selo":"OF","tipo":"discursiva","tema":"Kindling no transtorno bipolar","enun":"Responda: B. Explique o conceito de kindling no contexto da progressão do Transtorno Bipolar.","itens":[],"gab":"A hiperexcitabilidade crônica no SNC desencadeada pelas alterações promovidas pelo TB faz com que o SNC precise de gatilhos menores para desencadear as crises maníacas (resposta do aluno).","com":"Kindling (sensibilização): cada episódio deixa o cérebro mais suscetível, então os episódios seguintes surgem com estressores menores ou espontaneamente, e ficam mais frequentes."},{"id":"UC16-FIS-T11-Q13a","sp":2,"tus":["T11"],"prova":"T11 (2026/2) Q13a","selo":"OF","tipo":"discursiva","tema":"Episódio maníaco","enun":"Responda: A. Um jovem de 19 anos, com histórico de um episódio depressivo grave no ano anterior, apresenta-se há 10 dias com euforia exuberante, acredita que tem um plano para erradicar a fome mundial e parou de dormir, sem sentir cansaço. Ele foi detido após tentar entrar em um palácio governamental para dar ordens. A hipótese diagnóstica mais provável é:","itens":[],"gab":"Transtorno bipolar tipo I em fase maníaca (resposta do aluno, circulada pelo professor como certa).","com":"Há mais de 7 dias com grandiosidade delirante, redução da necessidade de sono e prejuízo grave (detenção): episódio maníaco, que basta para TB I."},{"id":"UC16-FIS-T11-Q13b","sp":4,"tus":["T11"],"prova":"T11 (2026/2) Q13b","selo":"OF","tipo":"discursiva","tema":"Esquizofrenia: fases","enun":"Responda: B. Paciente, masculino, de 21 anos abandonou a faculdade há 8 meses. Desde então, ele parou de tomar banho, não sai do seu quarto e perdeu o interesse por atividades sociais. Há 2 meses, começou a afirmar que vizinhos instalaram câmeras em seu ventilador e ouve vozes que narram seus movimentos. Pense em um diagnóstico provável e assinale em qual fase da doença ele se encontra no momento da consulta:","itens":[],"gab":"Esquizofrenia, em fase ativa (o professor anotou 'F. ativa' ao lado da resposta do aluno, que citou só os sintomas positivos, delírios e alucinações).","com":"Prodrômica de 6 meses (isolamento, autonegligência) seguida de delírios e alucinações há 2 meses: no momento, fase ativa (psicótica). Total de 8 meses, mais de 6."},{"id":"UC16-FIS-SN1-Q01","sp":3,"tus":["Sem turma"],"prova":"S/turma Q1","selo":"OF","tipo":"discursiva","tema":"Causas clínicas de ansiedade","enun":"Liste 3 distúrbios clínicos que podem produzir ansiedade diretamente","itens":[],"gab":"Feocromocitoma; IAM; terceiro item [ilegível] (resposta do aluno; 'síndrome do pânico' foi riscada; nota parcial).","com":"Exemplos clássicos: hipertireoidismo, feocromocitoma, hipoglicemia, arritmias/IAM, asma/DPOC, TEP. Transtorno de pânico não conta, porque não é distúrbio clínico.<br><b>Observação:</b> Nota parcial; terceiro item da resposta ilegível.","incerta":true},{"id":"UC16-FIS-SN1-Q02","sp":2,"tus":["Sem turma"],"prova":"S/turma Q2","selo":"OF","tipo":"direta","tema":"Hipomania","enun":"Assinale a alternativa que melhor define a hipomania:","itens":[],"alts":["Autoestima inflada ou grandiosidade, redução da necessidade de sono, mais loquaz que o habitual ou pressão para continuar falando, por um período mínimo de uma semana.","A perturbação do humor é suficientemente grave a ponto de causar prejuízo acentuado no funcionamento social ou profissional.","Um período distinto de humor anormal e persistentemente elevado, expansivo ou irritável, com aumento anormal da atividade ou energia, com duração mínima de quatro dias consecutivos.","Perda da capacidade de cuidar de si, estando sujeito ao cuidado familiar.","Período compreendido entre uma fase maníaca e uma fase depressiva."],"gab":"C","com":"Hipomania = humor elevado/irritável com mais energia por pelo menos 4 dias consecutivos. Uma semana e prejuízo acentuado definem mania."},{"id":"UC16-FIS-SN1-Q03","sp":3,"tus":["Sem turma"],"prova":"S/turma Q3","selo":"OF","tipo":"caso","tema":"Transtorno do pânico: sintomas","enun":"Paciente de 48 anos, foi diagnosticada pela equipe médica com transtorno do pânico. Ela apresenta vários sinais/sintomas, mas é necessária a conjugação de pelo menos quatro sinais/sintomas para tal identificação, que podem ser: (escolha a resposta mais correta)","itens":[],"alts":["Falta de ar, suor frio, taquicardia, tontura","Sudorese, cefaleia constante, tremores, dor no estômago","Zumbido no ouvido, diarreia, tontura, bradicardia","Taquicardia, calor, torpor, e formigamento","Tontura, dormência, desconforto torácico, calor"],"gab":"A","com":"Falta de ar, sudorese, taquicardia e tontura estão todos no DSM-5. Cefaleia constante, zumbido, bradicardia e torpor não estão."},{"id":"UC16-FIS-SN1-Q04","sp":4,"tus":["Sem turma"],"prova":"S/turma Q4","selo":"OF","tipo":"caso","tema":"Alteração do pensamento","enun":"Paciente atendido no CAPES não soube relatar uma queixa principal concisa, dizendo que estava \"preso no poder divino há 7 anos\" e que \"as deusas não entregam o seu ser\", contando vários relatos de conteúdo místico, e contado ainda sobre a viagem que faria para o polo norte. O sintoma que pode ser detectado no paciente é:","itens":[],"alts":["delírio","incongruência afetiva","discurso desorganizado","comportamento desorganizado","alucinação"],"gab":"C","com":"A ênfase está em não conseguir relatar uma queixa concisa e saltar entre conteúdos, o que caracteriza discurso desorganizado. O conteúdo místico também sugere delírio, e por isso a questão é polêmica.","rep":2},{"id":"UC16-FIS-SN1-Q05","sp":2,"tus":["Sem turma"],"prova":"S/turma Q5","selo":"OF","tipo":"caso","tema":"Ciclotimia","enun":"Um jovem de 18 anos apresenta há mais de dois anos um transtorno psiquiátrico que é marcado por vários períodos hipomaníacos e vários períodos de depressão que duram poucos dias, e seguem um curso irregular. O paciente não ficou sem os sintomas mais que dois meses consecutivos. Qual seria o seu diagnóstico?","itens":[],"alts":["Depressão Sazonal","Ciclotimia","Transtorno Bipolar","Transtorno Depressivo Persistente","Transtorno Depressivo Maior."],"gab":"B","com":"Na ciclotimia há, por pelo menos 2 anos, vários períodos de sintomas hipomaníacos e depressivos que não fecham critérios de episódio, sem intervalo livre maior que 2 meses."},{"id":"UC16-FIS-SN1-Q06a","sp":1,"tus":["Sem turma"],"prova":"S/turma Q6a","selo":"OF","tipo":"discursiva","tema":"Definição de depressão","enun":"Responda: A. Defina depressão (0,5)","itens":[],"gab":"Estado em que o paciente apresenta humor deprimido ou anedonia durante um período de pelo menos 2 semanas, todos os dias, durante todo o dia (resposta do aluno; questão 6 com nota cheia).","com":"Pelo DSM-5: humor deprimido e/ou anedonia na maior parte do dia, quase todos os dias, por ≥2 semanas, com pelo menos 5 sintomas no total e prejuízo funcional."},{"id":"UC16-FIS-SN1-Q06b","sp":1,"tus":["Sem turma"],"prova":"S/turma Q6b","selo":"OF","tipo":"discursiva","tema":"Exames para depressão secundária","enun":"Responda: B) Liste 2 exames laboratoriais que devem ser realizados para descartar doenças físicas que provocam de depressão, justificando a sua resposta (0,5)","itens":[],"gab":"TSH (com T3/T4) para descartar hipotireoidismo; cortisol (com ACTH) para descartar síndrome de Cushing (resposta do aluno; questão 6 com nota cheia).","com":"Hipotireoidismo e Cushing são causas endócrinas clássicas de depressão; B12/folato e hemograma também servem."},{"id":"UC16-FIS-SN1-Q07","sp":2,"tus":["Sem turma"],"prova":"S/turma Q7","selo":"OF","tipo":"sentenças","tema":"Transtorno bipolar","enun":"Analise as seguintes afirmativas sobre o transtorno bipolar e assinale abaixo a alternativa correta:","itens":["I. Indivíduos com hipomania com características mistas podem não perceber seus sintomas como hipomania, experimentando-os como depressão, com aumento de energia ou irritabilidade.","II. Os episódios maníacos e depressivos se alternam regularmente, havendo sequência de um episódios maníaco e depois um depressivo, e assim por diante.","III. Para o diagnóstico de transtorno bipolar tipo II é preciso pelo menos um episódio de mania que pode ter sido antecedido ou seguido por episódios depressivos maiores ou hipomaníacos","IV. No transtorno bipolar, ambas as fases, maníaca e depressiva, podem ocorrem alternadamente, porém em alguns pacientes só uma das fases se manifesta com mais frequência.","V. A Hipomania não se apresenta com sintomas psicóticos."],"alts":["I, II e IV","II, III e V","I, IV e V","III e IV","I, II e V"],"gab":"C","com":"II é falsa (não há alternância regular) e III descreve o tipo I, não o II."},{"id":"UC16-FIS-SN1-Q08","sp":3,"tus":["Sem turma"],"prova":"S/turma Q8","selo":"OF","tipo":"discursiva","tema":"Neurobiologia da ansiedade","enun":"Assinale com V as afirmativas corretas e com F afirmativas incorretas sobre o transtorno de ansiedade:","itens":["( ) A serotonina exerce um papel eminentemente ansiogênico na amígdala e na matéria cinzenta periaquedutal dorsal.","( ) O efeito ansiolítico do GABA parece consistir em reduzir o funcionamento de grupos neuronais do sistema límbico, inclusive a amígdala e o hipocampo.","( ) Na ansiedade, a dor torácica é causada exclusivamente por mecanismos cardíacos como espasmo coronário e isquemia.","( ) A relação entre o GABA e a ansiedade evidencia-se no fato de que todos os ansiolíticos conhecidos, facilitam sua ação.","( ) Os sintomas do transtorno de ansiedade tendem a ser crônicos e tem remissões e recidivas ao longo da vida, flutuando entre formas sindrômicas e subsindrômicas do transtorno."],"gab":"Sequência: F, V, F, V, V","com":"A serotonina tem papel duplo (ansiogênica na amígdala, ansiolítica na MCPD), e a dor torácica não é 'exclusivamente' cardíaca (há tensão muscular e hiperventilação)."},{"id":"UC16-FIS-SN1-Q09","sp":4,"tus":["Sem turma"],"prova":"S/turma Q9","selo":"OF","tipo":"direta","tema":"Esquizofrenia","enun":"Assinale a afirmativa incorreta sobre esquizofrenia:","itens":[],"alts":["Em geral, pacientes com esquizofrenia não mantem a clareza de consciência e capacidade intelectual, e apresentam déficits cognitivos que podem evoluir com o tempo.","Sintomas positivos são os sintomas que se apresentam durante os episódios de psicoses.","A catatonia é definida como um conjunto de movimentos, posturas e ações complexas cujo denominador comum é a sua involuntariedade.","Os sintomas psicóticos tendem a diminuir ao longo da vida, talvez pelo declínio normal na atividade dopaminérgica relacionada ao envelhecimento.","Para o diagnóstico da esquizofrenia, as manifestações que devem estar presentes (pelo menos uma das três) durante parte significativa do tempo em um mês ou mais são: alucinações, discurso desorganizado e delírios"],"gab":"A","com":"Na esquizofrenia a clareza de consciência e a capacidade intelectual em geral estão PRESERVADAS (alteração da consciência sugere delirium)."},{"id":"UC16-FIS-SN1-Q10a","sp":3,"tus":["Sem turma"],"prova":"S/turma Q10a","selo":"OF","tipo":"discursiva","tema":"Definição de ansiedade","enun":"Defina: A. Ansiedade","itens":[],"gab":"Preocupação excessiva, com medo de coisas que ainda não aconteceram (e que o paciente nem sabe se vão acontecer); quando dura 6 meses ou mais, com 3 ou mais sintomas (irritabilidade, inquietação, insônia, fadiga), configura TAG (respostas de dois alunos, ambas com nota cheia).","com":"Ansiedade é um estado de apreensão antecipatória diante de ameaça futura ou vaga, com componentes cognitivos e autonômicos."},{"id":"UC16-FIS-SN1-Q10b","sp":4,"tus":["Sem turma"],"prova":"S/turma Q10b","selo":"OF","tipo":"discursiva","tema":"Definição de delírio","enun":"Defina: B. Delírio","itens":[],"gab":"Crença falsa/irreal mantida pelo paciente, imutável mesmo à luz de evidências em contrário; há vários tipos (persecutório, de referência, erotomania, niilismo) (respostas de alunos com nota cheia).","com":"Delírio é alteração do conteúdo do pensamento; não confundir com delirium (alteração da consciência)."},{"id":"UC16-FIS-SN1-Q10c","sp":4,"tus":["Sem turma"],"prova":"S/turma Q10c","selo":"OF","tipo":"discursiva","tema":"Definição de alucinação","enun":"Defina: C. Alucinações","itens":[],"gab":"Percepção sem objeto real, que pode afetar qualquer sentido (audição, visão, olfato, paladar, tato), sendo a auditiva (ouvir vozes inexistentes) a mais comum na esquizofrenia (respostas de alunos com nota cheia).","com":"Alucinação é alteração da sensopercepção; a auditiva é típica da esquizofrenia, e a visual sugere causa orgânica."},{"id":"UC16-FIS-SN1-Q11","sp":1,"tus":["Sem turma"],"prova":"S/turma Q11","selo":"OF","tipo":"sentenças","tema":"Depressão","enun":"Analise as seguintes afirmativas sobre a depressão e assinale abaixo a resposta correta:","itens":["I. A diminuição da expressão de BDNF, e o aumento da liberação de cortisol estariam relacionadas com a depressão pós parto.","II. O diagnostico do transtorno depressivo maior baseado em um único episodio é possível, embora o transtorno seja recorrente na maioria dos casos","III. Os sintomas do transtorno depressivo persistente tipicamente começam de forma insidiosa durante a adolescência e podem persistir por muito anos ou décadas.","IV. Na depressão, citocinas pro inflamatórias podem alcançar o cérebro e induzir vias de sinalização inflamatória, incluindo o NF-kB , contribuindo prioritariamente para o metabolismo alterado de serotonina.","V. O transtorno depressivo persistente pode ser diagnosticada quando a perturbação do humor continua por pelo menos 6 meses sem remissão."],"alts":["I, II e III","II, III e IV","I, III, IV e V","I e II","II, III e V"],"gab":"A","com":"IV erra no 'prioritariamente serotonina' (o NF-kB altera o metabolismo das monoaminas em geral) e V erra no prazo (o TDP exige 2 anos)."},{"id":"UC16-FIS-SN1-Q12","sp":4,"tus":["Sem turma"],"prova":"S/turma Q12","selo":"OF","tipo":"discursiva","tema":"Esquizofrenia","enun":"Assinale com V as afirmativas corretas e com F as afirmativas incorretas sobre a esquizofrenia:","itens":["( ) Na esquizofrenia, os astrócitos podem estar envolvidos com uma alteração na espessura dos vasos do cérebro, levando diminuição no fluxo metabólico em certas regiões cerebrais.","( ) Os transtornos esquizofrênicos são caracterizados pelo embotamento afetivo, um efeito de indiferença, falta de afeto e incapacidade de sentir emoções.","( ) Na esquizofrenia, a estimulação excessiva da via dopaminérgica mesolímbica provocaria a liberação excessiva de dopamina no nucleus accumbens e o aparecimento dos sinais negativos.","( ) Acredita-se que pacientes com esquizofrenia têm menos responsividade em receptores NMDA do glutamato, o que diminuiria a transmissão glutamatérgica.","( ) Foi demonstrado que o consumo de canabinóides, não constitui um fator precipitante em indivíduos predispostos a apresentar esquizofrenia."],"gab":"Sequência: V, V, F, V, F","com":"A hiperatividade mesolímbica gera sinais POSITIVOS (os negativos vêm da hipoatividade mesocortical), e canabinoides são fator precipitante."}],"turmas":["T3","T5","T6","T7","T9","T10","T11","Sem turma"],"temas":["Esquizofrenia","Transtorno bipolar","Transtorno do pânico: sintomas","Hipomania","Transtorno depressivo maior","TDDH","Fisiopatologia da depressão","TAG","Bipolar tipo I","Depressão","Ciclotimia","Episódio maníaco","Bipolar tipo II","TAG: neurobiologia","Neurobiologia da ansiedade","Alteração do pensamento","TAG: critérios","Esquizofrenia: neurobiologia","Hipóteses da depressão","Critérios do TDM","Transtornos de humor","Causas clínicas de depressão","Alucinação","Diagnóstico diferencial: esquizofrenia, bipolar e pânico","TAG: critérios DSM-5","Transtorno depressivo persistente","TDDH: diagnóstico","Transtorno de pânico: diagnóstico","Cortisol e ansiedade","Esquizofrenia: vias dopaminérgicas","Esquizofrenia: critérios","Mania x hipomania","Esquizofrenia: fisiopatologia","TAG: fisiopatologia","Eixo HHA na depressão","Delírio","Neuroquímica do transtorno bipolar","Transtorno de pânico","Esquizofrenia: diagnóstico","Neuroquímica da mania","Hipótese monoaminérgica","Domínios sintomatológicos da esquizofrenia","Dor torácica na crise de ansiedade","Poda sináptica","Alterações cerebrais na esquizofrenia","Sintomas negativos","Sintomas da depressão","Neurobiologia da ansiedade e do pânico","Esquizofrenia: fisiopatologia e critérios","Dor torácica: diagnóstico diferencial","Hiperventilação no pânico","Hipótese do falso alarme de sufocamento","Kindling no transtorno bipolar","Esquizofrenia: fases","Causas clínicas de ansiedade","Definição de depressão","Exames para depressão secundária","Definição de ansiedade","Definição de delírio","Definição de alucinação"],"selos":{"OF":{"l":"gabarito do professor","c":"ok"},"VE":{"l":"resolução de veterano","c":"warn"},"IN":{"l":"resposta inferida","c":"warn"},"":{"l":"sem gabarito","c":"err"}}};
